    let efficienzaOraCalcolata = -1;
    let alpha = 0.05;

    database.medie_consumi[stagione][fascia] = Math.round((database.medie_consumi[stagione][fascia] * (1 - alpha)) + (consumoMedioOra * alpha));

    if (fascia === "GIORNO" && produzioneMediaOra > 100) {
