let query = `INSERT INTO storico_clima 
    (timestamp_evento, comando_ir, stato_ac, modalita, temp_impostata, temp_rilevata, humidex, vmc_velocita, humidex_living, humidex_bedroom, batteria_soc, temp_camera, temp_esterno, surplus_w) 
    VALUES (
        '${localISOTime}', 
        '${log.comando_ir_inviato}', 
        '${log.stato_ac_attuale}', 
        '${log.modalita_aria}', 
        ${log.temperatura_impostata_c}, 
        ${envv.temperatura_c}, 
        ${envv.humidex},
        ${log.vmc_velocita_attuale},
        ${envv.humidex_living},
        ${envv.humidex_bedroom},
        ${energy.powerwall_soc_percent},
        ${envv.temp_cameraMatrimoniale},
        ${log.temperatura_esterna_c},
        ${energy.surplus_w}
    );`;

return { topic: query };

// ==================================================
// 0. CONTROLLO DI COERENZA (SANITY CHECK) & FAIL-SAFE
// ==================================================
// --- CONTROLLO DI COERENZA E STATO PERSISTENTE ---
let variabiliCritiche = [
    { nome: "user_min_run_time", defaultVal: 15 },
    { nome: "user_min_off_time", defaultVal: 20 },
    { nome: "user_deficit_tolerance_time", defaultVal: 40 },
    { nome: "user_vmc_max_notte", defaultVal: 2 },
    { nome: "user_target_humidex_estate", defaultVal: 29.0 },
    { nome: "user_emergency_humidex_away", defaultVal: 33.0 },
    { nome: "grace_mode_solar", defaultVal: false }
];

let mancanti = [];

variabiliCritiche.forEach(v => {
    let val = global.get(v.nome, "file");
    if (val === undefined) {
        mancanti.push(v.nome);
        global.set(v.nome, v.defaultVal, "file");
    }
});

let msgHealth = {
    topic: "casa/clima/system_health/stat"
};

if (mancanti.length > 0) {
    node.warn("STATO SISTEMA INCONSISTENTE: Parametri globali mancanti su file -> " + mancanti.join(", "));
    msgHealth.payload = {
        stato: "INCONSISTENTE",
        motivo: "Mancanza di parametri globali persistenti, ripristinati i default",
        elementi_mancanti: mancanti,
        timestamp: Date.now()
    };
} else {
    msgHealth.payload = {
        stato: "NORMALE",
        timestamp: Date.now()
    };
}

// ==================================================
// 1. MEMORIZZAZIONE DEI DATI IN INGRESSO
// ==================================================
if (msg.topic === "system/boot") {
    // Boot sync
}
else if (msg.topic === "TeslaPowerwall/solar_instant_power") {
    flow.set("produzione", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/load_instant_power") {
    flow.set("consumo", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/site_instant_power") {
    flow.set("grid_power", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/battery_instant_power") {
    flow.set("battery_power", parseFloat(msg.payload), "file");
}
else if (msg.topic === "emon/planetary/altitude") {
    flow.set("sun_altitude", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/SOE") {
    let rawSoc = parseFloat(msg.payload);
    let lastValidSoc = flow.get("powerwall_soc", "file");

    if (lastValidSoc === undefined) {
        flow.set("powerwall_soc", rawSoc, "file");
    } else {
        let delta = Math.abs(rawSoc - lastValidSoc);
        if (delta <= 3.0) {
            flow.set("powerwall_soc", rawSoc, "file");
            flow.set("soc_glitch_count", 0, "file"); 
        } else {
            let glitchCount = flow.get("soc_glitch_count", "file") || 0;
            glitchCount++;
            if (glitchCount >= 5) {
                flow.set("powerwall_soc", rawSoc, "file");
                flow.set("soc_glitch_count", 0, "file");
            } else {
                flow.set("soc_glitch_count", glitchCount, "file");
            }
        }
    }
}
else if (msg.topic === "emon/emonth5/temperature_calibrated") {
    flow.set("temperatura", parseFloat(msg.payload),"file");
}
else if (msg.topic === "zara/domotics/LivingHumidex") {
    flow.set("humidex_giorno", parseFloat(msg.payload), "file");
}
else if (msg.topic === "zara/domotics/BedroomHumidex") {
    flow.set("humidex_notte", parseFloat(msg.payload), "file");
}
else if (msg.topic === "zigbee2mqtt/Sonoff AirGuard TH esterno cucina") {
    flow.set("temp_esterno", parseFloat(msg.payload.temperature));
    flow.set("umidita_esterno", parseFloat(msg.payload.humidity));
}
else if (msg.topic === "emon/cameraMatrimoniale/temperature") {
    flow.set("temp_cameraMatrimoniale", parseFloat(msg.payload));
}
else if (msg.topic === "emon/AC/emeter_power") {
    flow.set("ac_power", Math.abs(parseFloat(msg.payload)), "file"); 
}

let meseAttuale = new Date().getMonth();
let MODALITA_STAGIONE = (meseAttuale >= 4 && meseAttuale <= 8) ? "ESTATE" : "INVERNO";

let tempEsterna = flow.get("temp_esterno");
let umiditaEsterna = flow.get("umidita_esterno");

if (tempEsterna === undefined || umiditaEsterna === undefined) {
    tempEsterna = (MODALITA_STAGIONE === "ESTATE") ? 24 : 8;
    umiditaEsterna = 60;
}

let aEst = 17.27;
let bEst = 237.7;
let alphaEst = ((aEst * tempEsterna) / (bEst + tempEsterna)) + Math.log(umiditaEsterna / 100);
let dewPointEst = (bEst * alphaEst) / (aEst - alphaEst);
let eEst = 6.11 * Math.exp(5417.7530 * ((1 / 273.15) - (1 / (273.15 + dewPointEst))));
let humidexEsterno = parseFloat((tempEsterna + (5 / 9) * (eEst - 10)).toFixed(1));

let adesso = Date.now();
let statoAttuale = flow.get("condizionatore_stato", "file") || "OFF";

let ultimoAvvio = global.get("ultimo_avvio", "file") || (adesso - 40 * 60 * 1000);
let ultimoSpegnimento = global.get("ultimo_spegnimento", "file") || (adesso - 40 * 60 * 1000);

const MIN_RUN_MINUTI = parseFloat(global.get("user_min_run_time", "file")) || 15;
const MIN_OFF_MINUTI = parseFloat(global.get("user_min_off_time", "file")) || 15;
const DEFICIT_TOLERANCE_MINUTI = parseFloat(global.get("user_deficit_tolerance_time", "file")) || 10; 
const VMC_MAX_NOTTE = parseInt(global.get("user_vmc_max_notte", "file")) || 2;
const TARGET_HUMIDEX_ESTATE = parseFloat(global.get("user_target_humidex_estate", "file")) || 29;
const EMERGENCY_HUMIDEX_AWAY = parseFloat(global.get("user_emergency_humidex_away", "file")) || 33.0;

const MIN_RUN_TIME = MIN_RUN_MINUTI * 60 * 1000;
const MIN_OFF_TIME = MIN_OFF_MINUTI * 60 * 1000;
const DEFICIT_TOLERANCE_TIME = DEFICIT_TOLERANCE_MINUTI * 60 * 1000; 

let tempoPassatoDallAccensione = adesso - ultimoAvvio;
let tempoPassatoDalloSpegnimento = adesso - ultimoSpegnimento;

let minMancantiSpegnimento = tempoPassatoDallAccensione < MIN_RUN_TIME ? Math.ceil((MIN_RUN_TIME - tempoPassatoDallAccensione) / 60000) : 0;
let minMancantiAccensione = tempoPassatoDalloSpegnimento < MIN_OFF_TIME ? Math.ceil((MIN_OFF_TIME - tempoPassatoDalloSpegnimento) / 60000) : 0;
let tempoMancanteMinuti = (statoAttuale === "OFF") ? minMancantiAccensione : minMancantiSpegnimento;

// ==================================================
// 2. RECUPERO DERIVAZIONI ENERGETICHE E ASTRONOMICHE
// ==================================================
let prod = flow.get("produzione", "file") || 0;
let cons = flow.get("consumo", "file") || 0;
let soc = (flow.get("powerwall_soc", "file") !== undefined) ? flow.get("powerwall_soc", "file") : 0;
let temp = flow.get("temperatura", "file") || 19;
let hGiorno = flow.get("humidex_giorno", "file") || 0;
let hNotte = flow.get("humidex_notte", "file") || 0;
let temp_cameraMatrimoniale = flow.get("temp_cameraMatrimoniale") || 0;
let acPower = flow.get("ac_power", "file") || 0;

let gridPowerRaw = flow.get("grid_power", "file") || 0;
let batteryPowerRaw = flow.get("battery_power", "file") || 0;
let sunAltitude = flow.get("sun_altitude", "file"); 
if (sunAltitude === undefined) sunAltitude = 90; 

let gridImportW = Math.max(gridPowerRaw, 0);
let gridExportW = Math.max(-gridPowerRaw, 0);
let batteryDischargeW = Math.max(batteryPowerRaw, 0);
let batteryChargeW = Math.max(-batteryPowerRaw, 0);

let vmc_portata = [0, 50, 130, 160, 300];
let oraAttuale = new Date().getHours();
let surplus = prod - cons;

let kwhDomani = flow.get("previsione_kwh_domani") || 12;
let dataDomani = flow.get("previsione_data_domani") || "N/A";
let tutteMedie = flow.get("tutte_medie_storiche", "file") || global.get("tutte_medie_storiche", "file") || { ESTATE: { GIORNO: 600, NOTTE: 400 }, INVERNO: { GIORNO: 800, NOTTE: 500 } };

let dataOraFormattata = new Intl.DateTimeFormat('it-IT', {
    timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false
}).format(new Date(adesso));

let esNotteFascia = (oraAttuale >= 22 || oraAttuale < 8);
let humidex = esNotteFascia ? hNotte : hGiorno;
if (humidex === 0) humidex = (hGiorno !== 0) ? hGiorno : hNotte;

const CAPACITA_BATTERIA_KWH = 13.5;
let consumoDiurnoStimatoKwh = (tutteMedie[MODALITA_STAGIONE]["GIORNO"] * 12) / 1000;
if (isNaN(consumoDiurnoStimatoKwh) || consumoDiurnoStimatoKwh < 3) consumoDiurnoStimatoKwh = 7.5;

let energiaDisponibilePerBatteriaKwh = (kwhDomani - consumoDiurnoStimatoKwh) * 0.95;
if (energiaDisponibilePerBatteriaKwh < 0) energiaDisponibilePerBatteriaKwh = 0;

let socStimatoMattino = soc - 15;
if (socStimatoMattino < 0) socStimatoMattino = 0;
if (socStimatoMattino > 100) socStimatoMattino = 100; 

let capacitaVuotaKwh = CAPACITA_BATTERIA_KWH * (1 - (socStimatoMattino / 100));
let kwhDestinatiAllaBatteria = 0;
let percentualeRicaricaPrevista = 0;

if (energiaDisponibilePerBatteriaKwh >= capacitaVuotaKwh) {
    kwhDestinatiAllaBatteria = capacitaVuotaKwh;
    percentualeRicaricaPrevista = 100;
} else {
    kwhDestinatiAllaBatteria = energiaDisponibilePerBatteriaKwh;
    let ricaricaAggiuntivaPercentuale = (energiaDisponibilePerBatteriaKwh / CAPACITA_BATTERIA_KWH) * 100;
    percentualeRicaricaPrevista = Math.round(socStimatoMattino + ricaricaAggiuntivaPercentuale);
}

if (percentualeRicaricaPrevista > 100) percentualeRicaricaPrevista = 100;
if (percentualeRicaricaPrevista < 0) percentualeRicaricaPrevista = 0;

let comandoIR = null;
let sogliaAttivazioneLogica = 0;
let socMinimoLogico = 0;
let consumoStoricoAttuale = tutteMedie[MODALITA_STAGIONE][esNotteFascia ? "NOTTE" : "GIORNO"];

// --- Inizializzazione Variabili per Log e UI ---
let bloccoSpegnimentoEmergenza = false; 
let energiaDisponibileKwh = 0;
let consumoNotteStimatoKwh = 0;
let cuscinettoSicurezzaKwh = 0;
let cuscinettoMinimoRichiesto = 0;

// ==================================================
// 3. MASTER SWITCH E LOGICA INTEGRATA
// ==================================================
let aiAbilitata = flow.get("AI_climate_enabling", "file");
if (aiAbilitata === undefined) {
    aiAbilitata = true;
    flow.set("AI_climate_enabling", true, "file");
}
let systemWasDisabled = flow.get("system_was_disabled") || false;

let velocitaVmc = 1;
let motivoVmc = "STANDBY_MINIMO";
let motivoAc = "ANALISI_IN_CORSO";

if (!aiAbilitata) {
    if (!systemWasDisabled) {
        comandoIR = "OFF"; 
        statoAttuale = "OFF";
        flow.set("condizionatore_stato", "OFF", "file");
        flow.set("system_was_disabled", true);
        global.set("ultimo_spegnimento", adesso, "file");
    } else {
        statoAttuale = "OFF";
    }
    velocitaVmc = 1;
    motivoVmc = "SISTEMA_DISABILITATO";
    motivoAc = "SISTEMA_DISABILITATO_DA_UTENTE";
    tempoMancanteMinuti = 0;

} else {
    if (systemWasDisabled) {
        flow.set("system_was_disabled", false);
    }

    let bypassRoutine = false;

    if (statoAttuale !== "OFF" && acPower >= 10) {
        flow.set("tentativi_riavvio_ac", 0);
    }

    if (statoAttuale === "OFF" && acPower > 30 && (adesso - ultimoSpegnimento > 3 * 60 * 1000)) {
        comandoIR = "OFF";
        global.set("ultimo_spegnimento", adesso, "file"); 
        ultimoSpegnimento = adesso;                      
        motivoAc = "WATCHDOG_FALSO_OFF";
        bypassRoutine = true; 
    }
    else if (statoAttuale !== "OFF" && statoAttuale !== "STANDBY_INVERTER" && acPower < 10 && (adesso - ultimoAvvio > 6 * 60 * 1000)) {
        let tentativi = flow.get("tentativi_riavvio_ac") || 0;

        if (tentativi < 3) {
            tentativi++;
            flow.set("tentativi_riavvio_ac", tentativi);

            statoAttuale = "OFF";
            flow.set("condizionatore_stato", "OFF", "file");
            global.set("ultimo_spegnimento", adesso - MIN_OFF_TIME - 1000, "file");
            tempoMancanteMinuti = 0;
            minMancantiAccensione = 0;
            motivoAc = "WATCHDOG_TENTATIVO_RIAVVIO_" + tentativi;
        } else {
            aiAbilitata = false;
            flow.set("AI_climate_enabling", false, "file");
            flow.set("tentativi_riavvio_ac", 0);

            comandoIR = "OFF"; 
            statoAttuale = "OFF";
            flow.set("condizionatore_stato", "OFF", "file");
            global.set("ultimo_spegnimento", adesso, "file");
            motivoAc = "WATCHDOG_SOSPENSIONE_SISTEMA_GUASTO";
            bypassRoutine = true;
        }
    }

    if (!bypassRoutine && aiAbilitata) {
        if (MODALITA_STAGIONE === "INVERNO") {
            sogliaAttivazioneLogica = esNotteFascia ? 17.0 : 19.0;
            socMinimoLogico = esNotteFascia ? (kwhDomani >= 22 && consumoStoricoAttuale < 700 ? 25 : (kwhDomani <= 8 || consumoStoricoAttuale > 1000 ? 60 : 40)) : 0;
            motivoAc = "LOGICA_INVERNALE_ATTIVA";

            if (statoAttuale === "OFF") {
                if (!esNotteFascia && surplus > (consumoStoricoAttuale * 0.8) && temp < 19.0) {
                    if (minMancantiAccensione === 0) {
                        statoAttuale = "HEAT_DIURNO"; flow.set("condizionatore_stato", "HEAT_DIURNO", "file"); global.set("ultimo_avvio", adesso, "file"); comandoIR = "eco19heat";
                    }
                }
                else if (esNotteFascia && temp < 17.0 && soc > socMinimoLogico) {
                    if (minMancantiAccensione === 0) {
                        statoAttuale = "HEAT_SICUREZZA_NOTTE"; flow.set("condizionatore_stato", "HEAT_SICUREZZA_NOTTE", "file"); global.set("ultimo_avvio", adesso, "file"); comandoIR = "eco17heat";
                    }
                }
            } else {
                let richiediSpegnimentoInverno = false;
                if (statoAttuale === "HEAT_DIURNO" && (esNotteFascia || surplus < -150 || temp >= 19.5)) richiediSpegnimentoInverno = true;
                if (statoAttuale === "HEAT_SICUREZZA_NOTTE" && (!esNotteFascia || temp >= 17.5 || soc <= socMinimoLogico)) richiediSpegnimentoInverno = true;

                if (richiediSpegnimentoInverno && minMancantiSpegnimento === 0) {
                    statoAttuale = "OFF"; flow.set("condizionatore_stato", "OFF", "file"); global.set("ultimo_spegnimento", adesso, "file"); comandoIR = "OFF";
                }
            }
        }
        else if (MODALITA_STAGIONE === "ESTATE") {
            sogliaAttivazioneLogica = TARGET_HUMIDEX_ESTATE;

            let esSeraFasciaDinamica = (oraAttuale >= 15 && oraAttuale < 22 && sunAltitude <= 20);

            if (esNotteFascia) {
                socMinimoLogico = (kwhDomani >= 28 && consumoStoricoAttuale < 450 ? 20 : (kwhDomani <= 12 ? 55 : 35));
            } else if (esSeraFasciaDinamica) {

                energiaDisponibileKwh = (soc / 100) * CAPACITA_BATTERIA_KWH;
                let oreAllAlba = (8 + 24 - oraAttuale) % 24; 
                consumoNotteStimatoKwh = (tutteMedie["ESTATE"]["NOTTE"] * oreAllAlba) / 1000;
                cuscinettoSicurezzaKwh = energiaDisponibileKwh - consumoNotteStimatoKwh;

                cuscinettoMinimoRichiesto = 1.0; 
                if (percentualeRicaricaPrevista < 95) {
                    let deficitRicaricaPct = 95 - percentualeRicaricaPrevista;
                    cuscinettoMinimoRichiesto += (deficitRicaricaPct * 0.05);
                }

                if (batteryDischargeW > 2500) {
                    socMinimoLogico = 100; 
                    bloccoSpegnimentoEmergenza = true;
                    motivoAc = `PEAK_SHAVING_ATTIVO (Scarica: ${batteryDischargeW}W)`;
                } 
                else if (cuscinettoSicurezzaKwh < cuscinettoMinimoRichiesto) {
                    socMinimoLogico = 100; 
                    bloccoSpegnimentoEmergenza = true;
                    motivoAc = `SOPRAVVIVENZA_NOTTE_ATTIVA (Cusc: ${cuscinettoSicurezzaKwh.toFixed(1)} < Riq: ${cuscinettoMinimoRichiesto.toFixed(1)}kWh)`;
                } 
                else {
                    socMinimoLogico = 45; 
                }
            } else {
                socMinimoLogico = (global.get("grace_mode_solar", "file") === true) ? 85 : 35; 
            }

            let gracePeriodStr = global.get("grace_period_time_range", "file") || "8-16";
            let graceParts = gracePeriodStr.split("-");
            let graceStart = parseInt(graceParts[0]) || 8;
            let graceEnd = parseInt(graceParts[1]) || 16;

            let isPeriodoDiGrazia = (oraAttuale >= graceStart && oraAttuale < graceEnd);
            let usaSoloSolare = global.get("grace_mode_solar", "file") === true; 

            if (isPeriodoDiGrazia) {
                if (!usaSoloSolare) {
                    sogliaAttivazioneLogica = EMERGENCY_HUMIDEX_AWAY;
                }
            }

            let surplusVirtuale = (statoAttuale === "OFF") ? (surplus - 700) : surplus;
            let solareForteDaOff = (!esNotteFascia && percentualeRicaricaPrevista >= 90 && surplusVirtuale > 500);
            let solareForteAttivo = (!esNotteFascia && percentualeRicaricaPrevista >= 90 && surplus > 300);

            if (statoAttuale === "OFF") {
                let transizionePermessa = false;

                if (minMancantiAccensione > 0) {
                    motivoAc = "BLOCCO_TIMER_ANTICICLO_OFF";
                } else if (bloccoSpegnimentoEmergenza) {
                    // Mantiene il divieto e il motivo impostato dai controlli di sicurezza
                } else if (esNotteFascia) {
                    let ultimoSpegnimentoNotte = flow.get("ultimo_spegnimento_notte", "file") || 0;
                    let tempoMinimoPausaNotte = 45 * 60 * 1000;
                    let isteresiAccensioneNotte = 0.5;

                    if (soc <= socMinimoLogico) {
                        motivoAc = "BLOCCO_NOTTE_BATTERIA_BASSA";
                    } else if (humidex < (sogliaAttivazioneLogica + isteresiAccensioneNotte)) {
                        motivoAc = "COMFORT_NOTTURNO_RAGGIUNTO";
                    } else if ((adesso - ultimoSpegnimentoNotte) < tempoMinimoPausaNotte) {
                        motivoAc = "BLOCCO_NOTTE_PAUSA_45M";
                    } else {
                        motivoAc = "PRONTO_ACCENSIONE_NIGHT_DRY";
                    }
                } else {
                    if (isPeriodoDiGrazia && usaSoloSolare && surplus < 1000 && !solareForteDaOff) {
                        motivoAc = "BLOCCO_GRAZIA_VINCOLO_SOLARE";
                    } else if (soc < socMinimoLogico && humidex < EMERGENCY_HUMIDEX_AWAY && !solareForteDaOff) {
                        motivoAc = "BLOCCO_DIURNO_BATTERIA";
                    } else if (surplusVirtuale <= 150 && humidex < EMERGENCY_HUMIDEX_AWAY && !solareForteDaOff) {
                        motivoAc = "ATTESA_SURPLUS_SOLARE";
                    } else if (humidex < sogliaAttivazioneLogica) {
                        motivoAc = "COMFORT_DIURNO_RAGGIUNTO";
                    } else {
                        motivoAc = (solareForteDaOff && soc < socMinimoLogico) ? "PRONTO_ACCENSIONE_OVERRIDE_SOLARE" : "PRONTO_ACCENSIONE_COOLING";
                    }
                }

                if (bloccoSpegnimentoEmergenza) {
                    transizionePermessa = false; 
                } else if (esSeraFasciaDinamica) {
                    if (soc >= socMinimoLogico && humidex >= sogliaAttivazioneLogica) transizionePermessa = true;
                } else if (esNotteFascia) {
                    if (soc > 75 && humidex >= (sogliaAttivazioneLogica + 1.0)) transizionePermessa = true;
                } else {
                    if ((soc >= socMinimoLogico || solareForteDaOff) && surplusVirtuale > 150) transizionePermessa = true;
                    if (humidex >= EMERGENCY_HUMIDEX_AWAY) transizionePermessa = true;
                    if (isPeriodoDiGrazia && usaSoloSolare) {
                        if (surplus < 1000 && !solareForteDaOff) transizionePermessa = false;
                    }
                }

                if (!esNotteFascia && transizionePermessa && humidex >= sogliaAttivazioneLogica) {
                    if (minMancantiAccensione === 0) {
                        statoAttuale = "COOLING_ON"; flow.set("condizionatore_stato", "COOLING_ON", "file"); global.set("ultimo_avvio", adesso, "file");
                        if (temp >= 26) comandoIR = "23"; else if (temp >= 25) comandoIR = "24"; else if (temp >= 24) comandoIR = "23"; else if (temp >= 23) comandoIR = "22"; else comandoIR = "26";
                        motivoAc = "ESECUZIONE_ACCENSIONE_DIURNA";
                    }
                } else if (esNotteFascia && soc > socMinimoLogico) {
                    let ultimoSpegnimentoNotte = flow.get("ultimo_spegnimento_notte", "file") || 0;
                    let tempoMinimoPausaNotte = 45 * 60 * 1000;
                    let isteresiAccensioneNotte = 0.5; 

                    if (humidex >= (sogliaAttivazioneLogica + isteresiAccensioneNotte)) {
                        if ((adesso - ultimoSpegnimentoNotte) >= tempoMinimoPausaNotte && minMancantiAccensione === 0) {
                            statoAttuale = "NIGHT_DRY"; 
                            flow.set("condizionatore_stato", "NIGHT_DRY", "file"); 
                            global.set("ultimo_avvio", adesso, "file");

                            // --- SELEZIONE DINAMICA DEL COMANDO DRY IN BASE ALLA TEMPERATURA ---
                            if (temp > 27) {
                                comandoIR = "eco26dry";
                            } else if (temp >= 26) {
                                comandoIR = "eco25dry";
                            } else if (temp >= 25) {
                                comandoIR = "25dry";
                            } else if (temp >= 24) {
                                comandoIR = "24dry";
                            } else {
                                comandoIR = "23dry";
                            }
                            // -----------------------------------------------------------------

                            motivoAc = "ESECUZIONE_ACCENSIONE_NOTTURNA";
                        }
                    }
                }
            } 
            else {
                let richiediSpegnimento = false;
                let richiediStandby = false;

                if (!bloccoSpegnimentoEmergenza) {
                    motivoAc = `MANTENIMENTO_${statoAttuale}`;
                }

                if (statoAttuale === "COOLING_ON" || statoAttuale === "STANDBY_INVERTER") {
                    let limiteDeficitSurplus = soc > 95 ? -1500 : -300;

                    if (esSeraFasciaDinamica) {
                        if (soc > 90) limiteDeficitSurplus = -2000;      
                        else if (soc > 80) limiteDeficitSurplus = -1000; 
                        else if (soc > 70) limiteDeficitSurplus = -400;  
                        else limiteDeficitSurplus = -100;                
                    }

                    if (isPeriodoDiGrazia && usaSoloSolare) {
                        limiteDeficitSurplus = 500; 
                    }

                    let sogliaSpegnimentoComfort = 26;

                    if (isPeriodoDiGrazia && !usaSoloSolare) {
                        if (humidex > EMERGENCY_HUMIDEX_AWAY) {
                            sogliaSpegnimentoComfort = EMERGENCY_HUMIDEX_AWAY; 
                        } else {
                            richiediStandby = true; 
                        }
                    } else {
                        let ampiezzaIsteresi = 2.5; 
                        sogliaSpegnimentoComfort = sogliaAttivazioneLogica - ampiezzaIsteresi;
                    }

                    if (bloccoSpegnimentoEmergenza) {
                        richiediSpegnimento = true; 
                        flow.set("inizio_deficit_surplus", 0);
                    }
                    else if (humidex <= sogliaSpegnimentoComfort) {
                        richiediStandby = true;
                        flow.set("inizio_deficit_surplus", 0);
                        if (minMancantiSpegnimento > 0) motivoAc = "COMFORT_RAGGIUNTO_ATTESA_TIMER";
                        else motivoAc = "STANDBY_COMFORT_RAGGIUNTO";
                    }
                    else if (surplus < limiteDeficitSurplus) {
                        let inizioDeficit = flow.get("inizio_deficit_surplus") || 0;
                        if (inizioDeficit === 0) {
                            flow.set("inizio_deficit_surplus", adesso);
                            motivoAc = "DEFICIT_RILEVATO_AVVIO_TIMER";
                        } else {
                            if ((adesso - inizioDeficit) >= DEFICIT_TOLERANCE_TIME) {
                                if (soc < socMinimoLogico && !solareForteAttivo) {
                                    richiediSpegnimento = true; 
                                } else {
                                    richiediStandby = true; 
                                    motivoAc = "STANDBY_DEFICIT_SOLARE";
                                }
                            } else {
                                motivoAc = "TOLLERANZA_DEFICIT_IN_CORSO";
                            }
                        }
                    }
                    else {
                        if (flow.get("inizio_deficit_surplus")) {
                            flow.set("inizio_deficit_surplus", 0);
                        }

                        if (statoAttuale === "STANDBY_INVERTER" && humidex >= sogliaAttivazioneLogica) {
                            statoAttuale = "COOLING_ON"; 
                            flow.set("condizionatore_stato", "COOLING_ON", "file"); 
                            global.set("ultimo_avvio", adesso, "file");
                            if (temp >= 26) comandoIR = "23"; else if (temp >= 25) comandoIR = "24"; else if (temp >= 24) comandoIR = "23"; else if (temp >= 23) comandoIR = "22"; else comandoIR = "26";
                            motivoAc = "RIPRESA_COOLING_DA_STANDBY";
                        }
                    }

                    if ((soc <= socMinimoLogico && !solareForteAttivo && !bloccoSpegnimentoEmergenza) || esNotteFascia) {
                        richiediSpegnimento = true;
                        richiediStandby = false;
                    }
                }

                if (statoAttuale === "NIGHT_DRY") {
                    if (soc <= socMinimoLogico) {
                        richiediSpegnimento = true;
                        flow.set("ultimo_spegnimento_notte", adesso, "file");
                        if(minMancantiSpegnimento > 0) motivoAc = "BATTERIA_SCARICA_ATTESA_TIMER";
                    } else if (!esNotteFascia) {
                        richiediSpegnimento = true;
                    }
                }

                let eseguiSpegnimento = bloccoSpegnimentoEmergenza ? true : (richiediSpegnimento && minMancantiSpegnimento === 0);

                if (eseguiSpegnimento) {
                    statoAttuale = "OFF";
                    flow.set("condizionatore_stato", "OFF", "file");
                    global.set("ultimo_spegnimento", adesso, "file");
                    comandoIR = "OFF";
                    flow.set("inizio_deficit_surplus", 0); 
                    if (!bloccoSpegnimentoEmergenza) motivoAc = "ESECUZIONE_SPEGNIMENTO";
                } 
                else if (richiediStandby && statoAttuale !== "STANDBY_INVERTER" && minMancantiSpegnimento === 0) {
                    statoAttuale = "STANDBY_INVERTER";
                    flow.set("condizionatore_stato", "STANDBY_INVERTER", "file");
                    global.set("ultimo_spegnimento", adesso, "file");
                    comandoIR = "28"; 
                    flow.set("inizio_deficit_surplus", 0);
                    motivoAc = "ESECUZIONE_STANDBY_INVERTER";
                }
            }
        }
    }

    // ==================================================
    // B.3 LOGICA VMC 
    // ==================================================
    if (MODALITA_STAGIONE === "ESTATE") {
        if (tempEsterna < (temp - 1.5)) {
            velocitaVmc = 3;
            motivoVmc = "FREE_COOLING_ATTIVO";
        }
        else if (tempEsterna >= (temp + 0.5)) {
            velocitaVmc = 1;
            motivoVmc = "SCUDO_TERMICO_ATTIVO";
        }
        else {
            if (humidex >= 30 && humidexEsterno < (humidex + 2.0)) {
                velocitaVmc = 3;
                motivoVmc = "ESTRAZIONE_UMIDITA_ALTA";
            }
            else if (humidex >= 27 && humidexEsterno < (humidex + 2.0)) {
                velocitaVmc = 2;
                motivoVmc = "ESTRAZIONE_UMIDITA_MEDIA";
            }
            else {
                velocitaVmc = 1;
                motivoVmc = "RICAMBIO_ARIA_BASE";
            }
        }
    }
    else {
        let urInterna = esNotteFascia ? flow.get("umidita_bedroom") : flow.get("umidita_living");
        if (urInterna === undefined) urInterna = 50;

        if (urInterna >= 65) { velocitaVmc = 3; motivoVmc = "ANTI_CONDENSA_MASSIMO"; }
        else if (urInterna >= 55) { velocitaVmc = 2; motivoVmc = "ANTI_CONDENSA_MEDIO"; }
        else if (tempEsterna < (temp - 5.0) && urInterna < 50) { velocitaVmc = 1; motivoVmc = "SCUDO_TERMICO_INVERNALE_ATTIVO"; }
        else { velocitaVmc = 1; motivoVmc = "COMFORT_INVERNALE_BASE"; }
    }

    if (esNotteFascia && velocitaVmc > VMC_MAX_NOTTE) { velocitaVmc = VMC_MAX_NOTTE; motivoVmc = motivoVmc + "_LIMITATO_NOTTE"; }
}

let currentTime = Date.now();
let lastVmcChangeTime = flow.get('vmc_ultimo_cambio_ms') || 0;
let lastVmcSpeed = flow.get("vmc_velocita_inviata") || velocitaVmc; 
let cooldownMs = 5 * 60 * 1000; 

if (velocitaVmc !== lastVmcSpeed) {
    if (currentTime - lastVmcChangeTime < cooldownMs) {
        velocitaVmc = lastVmcSpeed;
        motivoVmc = "BLOCCO_ANTIRIMBALZO_ATTIVO";
    } else {
        flow.set('vmc_ultimo_cambio_ms', currentTime);
    }
}

flow.set("vmc_fanspeed", velocitaVmc);

if (!aiAbilitata) {
    flow.set("ac_log_temp", 0, "file");
    flow.set("ac_log_mode", "OFF", "file");
} else if (comandoIR) {
    let estrazioneTesto = comandoIR.match(/\d+/);
    let targetImpostato = estrazioneTesto ? parseFloat(estrazioneTesto[0]) : 0;

    if (comandoIR === "OFF" || comandoIR === "stop") { 
        flow.set("ac_log_temp", 0, "file"); flow.set("ac_log_mode", "OFF", "file"); 
    }
    else if (comandoIR.includes("dry")) { 
        flow.set("ac_log_temp", targetImpostato || 25.0, "file"); flow.set("ac_log_mode", "Deumidificazione", "file"); 
    }
    else if (comandoIR.includes("heat")) { 
        flow.set("ac_log_temp", targetImpostato || 19.0, "file"); flow.set("ac_log_mode", "Riscaldamento", "file"); 
    }
    else { 
        flow.set("ac_log_temp", targetImpostato || 24.0, "file"); flow.set("ac_log_mode", "Raffrescamento", "file"); 
    }
} else if (statoAttuale === "OFF") {
    flow.set("ac_log_temp", 0, "file"); flow.set("ac_log_mode", "OFF", "file");
}

let tempImpostata = flow.get("ac_log_temp", "file") || 0;
let modalitaAria = flow.get("ac_log_mode", "file") || "OFF";

// --- DATI PER L'APP ANDROID (UI E WIDGET) ---
let datiAndroid = {
    timestamp: adesso,
    data_ora_formattata: dataOraFormattata,
    stagione_attiva: MODALITA_STAGIONE,
    metriche_elettriche: {
        produzione_fv_w: prod, 
        consumo_casa_w: cons, 
        surplus_w: surplus,
        grid_power_w: gridPowerRaw,
        grid_import_w: gridImportW,
        grid_export_w: gridExportW,
        battery_power_w: batteryPowerRaw,
        battery_charge_w: batteryChargeW,
        battery_discharge_w: batteryDischargeW,
        powerwall_soc_percent: soc, 
        consumo_ac_w: acPower, 
        consumo_medio_storico_fascia_w: consumoStoricoAttuale
    },
    metriche_ambientali: {
        temp_cameraMatrimoniale: temp_cameraMatrimoniale, temperatura_c: temp,
        humidex: humidex, humidex_living: hGiorno, humidex_bedroom: hNotte,
        altitudine_sole: sunAltitude
    },
    logica_controllo: {
        vmc_portata_stimata_m3h: vmc_portata[velocitaVmc],
        stanza_rilevamento_vmc: esNotteFascia ? "BEDROOM" : "LIVING",
        soglia_attivazione_applicata: sogliaAttivazioneLogica,
        soc_minimo_applied: socMinimoLogico,
        tempo_mancante_anticiclo_minuti: tempoMancanteMinuti,
        previsione_solare_domani_kwh: kwhDomani, previsione_solare_data: dataDomani,
        previsione_ricarica_batteria_percent: percentualeRicaricaPrevista, 
        kwh_stimati_in_batteria: parseFloat(kwhDestinatiAllaBatteria.toFixed(1)),
        blocco_emergenza_attivo: bloccoSpegnimentoEmergenza,
        cuscinetto_sicurezza_kwh: parseFloat(cuscinettoSicurezzaKwh.toFixed(2)),
        cuscinetto_richiesto_kwh: parseFloat(cuscinettoMinimoRichiesto.toFixed(2))
    },
    stato_condizionatore: {
        stato_attuale: statoAttuale,
        motivo_logica: motivoAc,
        temperatura_impostata_c: tempImpostata,
        modalita_aria: modalitaAria
    },
    stato_vmc: {
        velocita_attuale: velocitaVmc, motivo_logica: motivoVmc,
        humidex_esterno: humidexEsterno, temperatura_esterna_c: tempEsterna
    }
};

// --- LOGGING STRUTTURATO PER STORICO E GRAFANA ---
let msgLog = null;
let precedenteStatoAC = flow.get("log_ultimo_stato_ac") || "OFF";
let precedenteVelocitaVMC = flow.get("log_ultima_vmc") || 1;
let precedenteMotivoAC = flow.get("log_ultimo_motivo_ac") || "";

if (comandoIR || statoAttuale !== precedenteStatoAC || velocitaVmc !== precedenteVelocitaVMC || motivoAc !== precedenteMotivoAC) {
    msgLog = {
        payload: {
            timestamp: adesso, data_ora: dataOraFormattata, evento: "CAMBIO_STATO_SISTEMA",
            dettaglio_comandi: {
                comando_ir_inviato: comandoIR || "NESSUNO", stato_ac_precedente: precedenteStatoAC, stato_ac_attuale: statoAttuale,
                vmc_velocita_precedente: precedenteVelocitaVMC, vmc_velocita_attuale: velocitaVmc, motivo_logica: motivoVmc,
                humidex_esterno: humidexEsterno, temperatura_esterna_c: tempEsterna, modalita_aria: modalitaAria, temperatura_impostata_c: tempImpostata
            },
            condizioni_ambientali: { 
                humidex_living: hGiorno, humidex_bedroom: hNotte, temperatura_c: temp, temp_cameraMatrimoniale: temp_cameraMatrimoniale, 
                humidex: humidex, stanza_rilevamento: esNotteFascia ? "BEDROOM" : "LIVING", altitudine_sole: sunAltitude 
            },
            stato_energia: { 
                produzione_w: prod, consumo_w: cons, surplus_w: surplus, powerwall_soc_percent: soc, consumo_ac_w: acPower, soc_minimo_applied: socMinimoLogico,
                grid_import_w: gridImportW, grid_export_w: gridExportW, battery_charge_w: batteryChargeW, battery_discharge_w: batteryDischargeW
            },
            logica_controllo: { 
                previsione_solare_domani_kwh: kwhDomani, previsione_solare_data: dataDomani, previsione_ricarica_batteria_percent: percentualeRicaricaPrevista, 
                kwh_stimati_in_batteria: parseFloat(kwhDestinatiAllaBatteria.toFixed(1)), motivo_ac: motivoAc,
                blocco_emergenza_attivo: bloccoSpegnimentoEmergenza, cuscinetto_sicurezza_kwh: parseFloat(cuscinettoSicurezzaKwh.toFixed(2)),
                cuscinetto_richiesto_kwh: parseFloat(cuscinettoMinimoRichiesto.toFixed(2))
            }
        },
        topic: "casa/clima/log_eventi"
    };
    flow.set("log_ultimo_stato_ac", statoAttuale);
    flow.set("log_ultima_vmc", velocitaVmc);
    flow.set("log_ultimo_motivo_ac", motivoAc);
}

let msgBroadlink = comandoIR ? { payload: comandoIR, topic: "broadlink/cmd" } : null;
let baseTopic = global.get("app_base_topic", "file") || "zara/android/domotica";
let msgAndroid = { payload: datiAndroid, topic: `${baseTopic}/casa/clima/stato_completo` };

let ultimaVelocitaInviata = flow.get("vmc_velocita_inviata") || -1;
let msgVmc = null; 

if (velocitaVmc !== ultimaVelocitaInviata) {
    msgVmc = { topic: "/esp8266/brink/fanspeed", payload: velocitaVmc };
    flow.set("vmc_velocita_inviata", velocitaVmc);
}

return [msgBroadlink, msgAndroid, msgVmc, msgLog, msgHealth];

/*
 * PR-ARB.4D.3B
 * Startup race probe
 *
 * READ ONLY
 * No MQTT OUT
 * No actuator
 * No state modification
 */

const now = Date.now();

const gate =
    global.get("pr_arbitration_gate");

let consumerAction;
let consumerReason;

if (
    gate &&
    typeof gate === "object" &&
    gate.schema ===
        "domopi.predictive_reserve.arbitration_gate.v1" &&
    typeof gate.control_enabled === "boolean"
) {

    if (gate.control_enabled === false) {
        consumerAction = "BYPASS";
        consumerReason = "PR_CONTROL_DISABLED";
    }

    else if (gate.effective_authority !== true) {
        consumerAction = "DENY";
        consumerReason = "PR_NOT_AUTHORIZED";
    }

    else {
        consumerAction = "GATE_AVAILABLE";
        consumerReason = "CONTINUE_SNAPSHOT_EVALUATION";
    }

} else {

    consumerAction = "DENY";
    consumerReason = "PR_GATE_INVALID";
}

msg.topic = "pr/test/arb_4d_3b";

msg.payload = {
    test: "PR-ARB.4D.3B",
    timestamp_ms: now,

    gate_present:
        !!gate,

    gate:
        gate || null,

    consumer_view: {
        action:
            consumerAction,

        reason:
            consumerReason
    },

    safety: {
        read_only:
            true,
        mqtt_out:
            false,
        actuator_path:
            false,
        state_modified:
            false
    }
};

return msg;

// ==================================================
// 0. CONTROLLO DI COERENZA (SANITY CHECK) & FAIL-SAFE
// ==================================================
// --- CONTROLLO DI COERENZA E STATO PERSISTENTE ---
let variabiliCritiche = [
    { nome: "user_min_run_time", defaultVal: 15 },
    { nome: "user_min_off_time", defaultVal: 20 },
    { nome: "user_deficit_tolerance_time", defaultVal: 40 },
    { nome: "user_vmc_max_notte", defaultVal: 2 },
    { nome: "user_target_humidex_estate", defaultVal: 29.0 },
    { nome: "user_emergency_humidex_away", defaultVal: 33.0 },
    { nome: "grace_mode_solar", defaultVal: false }
];

let mancanti = [];

variabiliCritiche.forEach(v => {
    let val = global.get(v.nome, "file");
    if (val === undefined) {
        mancanti.push(v.nome);
        global.set(v.nome, v.defaultVal, "file");
    }
});

let msgHealth = {
    topic: "casa/clima/system_health/stat"
};

if (mancanti.length > 0) {
    node.warn("STATO SISTEMA INCONSISTENTE: Parametri globali mancanti su file -> " + mancanti.join(", "));
    msgHealth.payload = {
        stato: "INCONSISTENTE",
        motivo: "Mancanza di parametri globali persistenti, ripristinati i default",
        elementi_mancanti: mancanti,
        timestamp: Date.now()
    };
} else {
    msgHealth.payload = {
        stato: "NORMALE",
        timestamp: Date.now()
    };
}

// ==================================================
// 1. MEMORIZZAZIONE DEI DATI IN INGRESSO
// ==================================================
if (msg.topic === "system/boot") {
    // Boot sync
}
else if (msg.topic === "TeslaPowerwall/solar_instant_power") {
    flow.set("produzione", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/load_instant_power") {
    flow.set("consumo", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/site_instant_power") {
    flow.set("grid_power", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/battery_instant_power") {
    flow.set("battery_power", parseFloat(msg.payload), "file");
}
else if (msg.topic === "emon/planetary/altitude") {
    flow.set("sun_altitude", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/SOE") {
    let rawSoc = parseFloat(msg.payload);
    let lastValidSoc = flow.get("powerwall_soc", "file");

    if (lastValidSoc === undefined) {
        flow.set("powerwall_soc", rawSoc, "file");
    } else {
        let delta = Math.abs(rawSoc - lastValidSoc);
        if (delta <= 3.0) {
            flow.set("powerwall_soc", rawSoc, "file");
            flow.set("soc_glitch_count", 0, "file"); 
        } else {
            let glitchCount = flow.get("soc_glitch_count", "file") || 0;
            glitchCount++;
            if (glitchCount >= 5) {
                flow.set("powerwall_soc", rawSoc, "file");
                flow.set("soc_glitch_count", 0, "file");
            } else {
                flow.set("soc_glitch_count", glitchCount, "file");
            }
        }
    }
}
else if (msg.topic === "emon/emonth5/temperature_calibrated") {
    flow.set("temperatura", parseFloat(msg.payload),"file");
}
else if (msg.topic === "zara/domotics/LivingHumidex") {
    flow.set("humidex_giorno", parseFloat(msg.payload), "file");
}
else if (msg.topic === "zara/domotics/BedroomHumidex") {
    flow.set("humidex_notte", parseFloat(msg.payload), "file");
}
else if (msg.topic === "zigbee2mqtt/Sonoff AirGuard TH esterno cucina") {
    flow.set("temp_esterno", parseFloat(msg.payload.temperature));
    flow.set("umidita_esterno", parseFloat(msg.payload.humidity));
}
else if (msg.topic === "emon/cameraMatrimoniale/temperature") {
    flow.set("temp_cameraMatrimoniale", parseFloat(msg.payload));
}
else if (msg.topic === "emon/AC/emeter_power") {
    flow.set("ac_power", Math.abs(parseFloat(msg.payload)), "file"); 
}

let meseAttuale = new Date().getMonth();
let MODALITA_STAGIONE = (meseAttuale >= 4 && meseAttuale <= 8) ? "ESTATE" : "INVERNO";

let tempEsterna = flow.get("temp_esterno");
let umiditaEsterna = flow.get("umidita_esterno");

if (tempEsterna === undefined || umiditaEsterna === undefined) {
    tempEsterna = (MODALITA_STAGIONE === "ESTATE") ? 24 : 8;
    umiditaEsterna = 60;
}

let aEst = 17.27;
let bEst = 237.7;
let alphaEst = ((aEst * tempEsterna) / (bEst + tempEsterna)) + Math.log(umiditaEsterna / 100);
let dewPointEst = (bEst * alphaEst) / (aEst - alphaEst);
let eEst = 6.11 * Math.exp(5417.7530 * ((1 / 273.15) - (1 / (273.15 + dewPointEst))));
let humidexEsterno = parseFloat((tempEsterna + (5 / 9) * (eEst - 10)).toFixed(1));

let adesso = Date.now();
let statoAttuale = flow.get("condizionatore_stato", "file") || "OFF";

let ultimoAvvio = global.get("ultimo_avvio", "file") || (adesso - 40 * 60 * 1000);
let ultimoSpegnimento = global.get("ultimo_spegnimento", "file") || (adesso - 40 * 60 * 1000);

const MIN_RUN_MINUTI = parseFloat(global.get("user_min_run_time", "file")) || 15;
const MIN_OFF_MINUTI = parseFloat(global.get("user_min_off_time", "file")) || 15;
const DEFICIT_TOLERANCE_MINUTI = parseFloat(global.get("user_deficit_tolerance_time", "file")) || 10; 
const VMC_MAX_NOTTE = parseInt(global.get("user_vmc_max_notte", "file")) || 2;
const TARGET_HUMIDEX_ESTATE = parseFloat(global.get("user_target_humidex_estate", "file")) || 29;
const EMERGENCY_HUMIDEX_AWAY = parseFloat(global.get("user_emergency_humidex_away", "file")) || 33.0;

const MIN_RUN_TIME = MIN_RUN_MINUTI * 60 * 1000;
const MIN_OFF_TIME = MIN_OFF_MINUTI * 60 * 1000;
const DEFICIT_TOLERANCE_TIME = DEFICIT_TOLERANCE_MINUTI * 60 * 1000; 

let tempoPassatoDallAccensione = adesso - ultimoAvvio;
let tempoPassatoDalloSpegnimento = adesso - ultimoSpegnimento;

let minMancantiSpegnimento = tempoPassatoDallAccensione < MIN_RUN_TIME ? Math.ceil((MIN_RUN_TIME - tempoPassatoDallAccensione) / 60000) : 0;
let minMancantiAccensione = tempoPassatoDalloSpegnimento < MIN_OFF_TIME ? Math.ceil((MIN_OFF_TIME - tempoPassatoDalloSpegnimento) / 60000) : 0;
let tempoMancanteMinuti = (statoAttuale === "OFF") ? minMancantiAccensione : minMancantiSpegnimento;

// ==================================================
// 2. RECUPERO DERIVAZIONI ENERGETICHE E ASTRONOMICHE
// ==================================================
let prod = flow.get("produzione", "file") || 0;
let cons = flow.get("consumo", "file") || 0;
let soc = (flow.get("powerwall_soc", "file") !== undefined) ? flow.get("powerwall_soc", "file") : 0;
let temp = flow.get("temperatura", "file") || 19;
let hGiorno = flow.get("humidex_giorno", "file") || 0;
let hNotte = flow.get("humidex_notte", "file") || 0;
let temp_cameraMatrimoniale = flow.get("temp_cameraMatrimoniale") || 0;
let acPower = flow.get("ac_power", "file") || 0;

let gridPowerRaw = flow.get("grid_power", "file") || 0;
let batteryPowerRaw = flow.get("battery_power", "file") || 0;
let sunAltitude = flow.get("sun_altitude", "file"); 
if (sunAltitude === undefined) sunAltitude = 90; 

let gridImportW = Math.max(gridPowerRaw, 0);
let gridExportW = Math.max(-gridPowerRaw, 0);
let batteryDischargeW = Math.max(batteryPowerRaw, 0);
let batteryChargeW = Math.max(-batteryPowerRaw, 0);

let vmc_portata = [0, 50, 130, 160, 300];
let oraAttuale = new Date().getHours();
let surplus = prod - cons;

let kwhDomani = flow.get("previsione_kwh_domani") || 12;
let dataDomani = flow.get("previsione_data_domani") || "N/A";
let tutteMedie = flow.get("tutte_medie_storiche", "file") || global.get("tutte_medie_storiche", "file") || { ESTATE: { GIORNO: 600, NOTTE: 400 }, INVERNO: { GIORNO: 800, NOTTE: 500 } };

let dataOraFormattata = new Intl.DateTimeFormat('it-IT', {
    timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false
}).format(new Date(adesso));

let esNotteFascia = (oraAttuale >= 22 || oraAttuale < 8);
let humidex = esNotteFascia ? hNotte : hGiorno;
if (humidex === 0) humidex = (hGiorno !== 0) ? hGiorno : hNotte;

const CAPACITA_BATTERIA_KWH = 13.5;
let consumoDiurnoStimatoKwh = (tutteMedie[MODALITA_STAGIONE]["GIORNO"] * 12) / 1000;
if (isNaN(consumoDiurnoStimatoKwh) || consumoDiurnoStimatoKwh < 3) consumoDiurnoStimatoKwh = 7.5;

let energiaDisponibilePerBatteriaKwh = (kwhDomani - consumoDiurnoStimatoKwh) * 0.95;
if (energiaDisponibilePerBatteriaKwh < 0) energiaDisponibilePerBatteriaKwh = 0;

let socStimatoMattino = soc - 15;
if (socStimatoMattino < 0) socStimatoMattino = 0;
if (socStimatoMattino > 100) socStimatoMattino = 100; 

let capacitaVuotaKwh = CAPACITA_BATTERIA_KWH * (1 - (socStimatoMattino / 100));
let kwhDestinatiAllaBatteria = 0;
let percentualeRicaricaPrevista = 0;

if (energiaDisponibilePerBatteriaKwh >= capacitaVuotaKwh) {
    kwhDestinatiAllaBatteria = capacitaVuotaKwh;
    percentualeRicaricaPrevista = 100;
} else {
    kwhDestinatiAllaBatteria = energiaDisponibilePerBatteriaKwh;
    let ricaricaAggiuntivaPercentuale = (energiaDisponibilePerBatteriaKwh / CAPACITA_BATTERIA_KWH) * 100;
    percentualeRicaricaPrevista = Math.round(socStimatoMattino + ricaricaAggiuntivaPercentuale);
}

if (percentualeRicaricaPrevista > 100) percentualeRicaricaPrevista = 100;
if (percentualeRicaricaPrevista < 0) percentualeRicaricaPrevista = 0;

let comandoIR = null;
let sogliaAttivazioneLogica = 0;
let socMinimoLogico = 0;
let consumoStoricoAttuale = tutteMedie[MODALITA_STAGIONE][esNotteFascia ? "NOTTE" : "GIORNO"];

// --- Inizializzazione Variabili per Log e UI ---
let bloccoSpegnimentoEmergenza = false; 
let energiaDisponibileKwh = 0;
let consumoNotteStimatoKwh = 0;
let cuscinettoSicurezzaKwh = 0;
let cuscinettoMinimoRichiesto = 0;

// ==================================================
// 3. MASTER SWITCH E LOGICA INTEGRATA
// ==================================================
let aiAbilitata = flow.get("AI_climate_enabling", "file");
if (aiAbilitata === undefined) {
    aiAbilitata = true;
    flow.set("AI_climate_enabling", true, "file");
}
let systemWasDisabled = flow.get("system_was_disabled") || false;

let velocitaVmc = 1;
let motivoVmc = "STANDBY_MINIMO";
let motivoAc = "ANALISI_IN_CORSO";

if (!aiAbilitata) {
    if (!systemWasDisabled) {
        comandoIR = "OFF"; 
        statoAttuale = "OFF";
        flow.set("condizionatore_stato", "OFF", "file");
        flow.set("system_was_disabled", true);
        global.set("ultimo_spegnimento", adesso, "file");
    } else {
        statoAttuale = "OFF";
    }
    velocitaVmc = 1;
    motivoVmc = "SISTEMA_DISABILITATO";
    motivoAc = "SISTEMA_DISABILITATO_DA_UTENTE";
    tempoMancanteMinuti = 0;

} else {
    if (systemWasDisabled) {
        flow.set("system_was_disabled", false);
    }

    let bypassRoutine = false;

    if (statoAttuale !== "OFF" && acPower >= 10) {
        flow.set("tentativi_riavvio_ac", 0);
    }

    if (statoAttuale === "OFF" && acPower > 30 && (adesso - ultimoSpegnimento > 3 * 60 * 1000)) {
        comandoIR = "OFF";
        global.set("ultimo_spegnimento", adesso, "file"); 
        ultimoSpegnimento = adesso;                      
        motivoAc = "WATCHDOG_FALSO_OFF";
        bypassRoutine = true; 
    }
    else if (statoAttuale !== "OFF" && statoAttuale !== "STANDBY_INVERTER" && acPower < 10 && (adesso - ultimoAvvio > 6 * 60 * 1000)) {
        let tentativi = flow.get("tentativi_riavvio_ac") || 0;

        if (tentativi < 3) {
            tentativi++;
            flow.set("tentativi_riavvio_ac", tentativi);

            statoAttuale = "OFF";
            flow.set("condizionatore_stato", "OFF", "file");
            global.set("ultimo_spegnimento", adesso - MIN_OFF_TIME - 1000, "file");
            tempoMancanteMinuti = 0;
            minMancantiAccensione = 0;
            motivoAc = "WATCHDOG_TENTATIVO_RIAVVIO_" + tentativi;
        } else {
            aiAbilitata = false;
            flow.set("AI_climate_enabling", false, "file");
            flow.set("tentativi_riavvio_ac", 0);

            comandoIR = "OFF"; 
            statoAttuale = "OFF";
            flow.set("condizionatore_stato", "OFF", "file");
            global.set("ultimo_spegnimento", adesso, "file");
            motivoAc = "WATCHDOG_SOSPENSIONE_SISTEMA_GUASTO";
            bypassRoutine = true;
        }
    }

    if (!bypassRoutine && aiAbilitata) {
        if (MODALITA_STAGIONE === "INVERNO") {
            sogliaAttivazioneLogica = esNotteFascia ? 17.0 : 19.0;
            socMinimoLogico = esNotteFascia ? (kwhDomani >= 22 && consumoStoricoAttuale < 700 ? 25 : (kwhDomani <= 8 || consumoStoricoAttuale > 1000 ? 60 : 40)) : 0;
            motivoAc = "LOGICA_INVERNALE_ATTIVA";

            if (statoAttuale === "OFF") {
                if (!esNotteFascia && surplus > (consumoStoricoAttuale * 0.8) && temp < 19.0) {
                    if (minMancantiAccensione === 0) {
                        statoAttuale = "HEAT_DIURNO"; flow.set("condizionatore_stato", "HEAT_DIURNO", "file"); global.set("ultimo_avvio", adesso, "file"); comandoIR = "eco19heat";
                    }
                }
                else if (esNotteFascia && temp < 17.0 && soc > socMinimoLogico) {
                    if (minMancantiAccensione === 0) {
                        statoAttuale = "HEAT_SICUREZZA_NOTTE"; flow.set("condizionatore_stato", "HEAT_SICUREZZA_NOTTE", "file"); global.set("ultimo_avvio", adesso, "file"); comandoIR = "eco17heat";
                    }
                }
            } else {
                let richiediSpegnimentoInverno = false;
                if (statoAttuale === "HEAT_DIURNO" && (esNotteFascia || surplus < -150 || temp >= 19.5)) richiediSpegnimentoInverno = true;
                if (statoAttuale === "HEAT_SICUREZZA_NOTTE" && (!esNotteFascia || temp >= 17.5 || soc <= socMinimoLogico)) richiediSpegnimentoInverno = true;

                if (richiediSpegnimentoInverno && minMancantiSpegnimento === 0) {
                    statoAttuale = "OFF"; flow.set("condizionatore_stato", "OFF", "file"); global.set("ultimo_spegnimento", adesso, "file"); comandoIR = "OFF";
                }
            }
        }
        else if (MODALITA_STAGIONE === "ESTATE") {
            sogliaAttivazioneLogica = TARGET_HUMIDEX_ESTATE;

            let esSeraFasciaDinamica = (oraAttuale >= 15 && oraAttuale < 22 && sunAltitude <= 20);

            if (esNotteFascia) {
                socMinimoLogico = (kwhDomani >= 28 && consumoStoricoAttuale < 450 ? 20 : (kwhDomani <= 12 ? 55 : 35));
            } else if (esSeraFasciaDinamica) {

                energiaDisponibileKwh = (soc / 100) * CAPACITA_BATTERIA_KWH;
                let oreAllAlba = (8 + 24 - oraAttuale) % 24; 
                consumoNotteStimatoKwh = (tutteMedie["ESTATE"]["NOTTE"] * oreAllAlba) / 1000;
                cuscinettoSicurezzaKwh = energiaDisponibileKwh - consumoNotteStimatoKwh;

                cuscinettoMinimoRichiesto = 1.0; 
                if (percentualeRicaricaPrevista < 95) {
                    let deficitRicaricaPct = 95 - percentualeRicaricaPrevista;
                    cuscinettoMinimoRichiesto += (deficitRicaricaPct * 0.05);
                }

                if (batteryDischargeW > 2500) {
                    socMinimoLogico = 100; 
                    bloccoSpegnimentoEmergenza = true;
                    motivoAc = `PEAK_SHAVING_ATTIVO (Scarica: ${batteryDischargeW}W)`;
                } 
                else if (cuscinettoSicurezzaKwh < cuscinettoMinimoRichiesto) {
                    socMinimoLogico = 100; 
                    bloccoSpegnimentoEmergenza = true;
                    motivoAc = `SOPRAVVIVENZA_NOTTE_ATTIVA (Cusc: ${cuscinettoSicurezzaKwh.toFixed(1)} < Riq: ${cuscinettoMinimoRichiesto.toFixed(1)}kWh)`;
                } 
                else {
                    socMinimoLogico = 45; 
                }
            } else {
                socMinimoLogico = (global.get("grace_mode_solar", "file") === true) ? 85 : 35; 
            }

            let gracePeriodStr = global.get("grace_period_time_range", "file") || "8-16";
            let graceParts = gracePeriodStr.split("-");
            let graceStart = parseInt(graceParts[0]) || 8;
            let graceEnd = parseInt(graceParts[1]) || 16;

            let isPeriodoDiGrazia = (oraAttuale >= graceStart && oraAttuale < graceEnd);
            let usaSoloSolare = global.get("grace_mode_solar", "file") === true; 

            if (isPeriodoDiGrazia) {
                if (!usaSoloSolare) {
                    sogliaAttivazioneLogica = EMERGENCY_HUMIDEX_AWAY;
                }
            }

            let surplusVirtuale = (statoAttuale === "OFF") ? (surplus - 700) : surplus;
            let solareForteDaOff = (!esNotteFascia && percentualeRicaricaPrevista >= 90 && surplusVirtuale > 500);
            let solareForteAttivo = (!esNotteFascia && percentualeRicaricaPrevista >= 90 && surplus > 300);

            if (statoAttuale === "OFF") {
                let transizionePermessa = false;

                if (minMancantiAccensione > 0) {
                    motivoAc = "BLOCCO_TIMER_ANTICICLO_OFF";
                } else if (bloccoSpegnimentoEmergenza) {
                    // Mantiene il divieto e il motivo impostato dai controlli di sicurezza
                } else if (esNotteFascia) {
                    let ultimoSpegnimentoNotte = flow.get("ultimo_spegnimento_notte", "file") || 0;
                    let tempoMinimoPausaNotte = 45 * 60 * 1000;
                    let isteresiAccensioneNotte = 0.5;

                    if (soc <= socMinimoLogico) {
                        motivoAc = "BLOCCO_NOTTE_BATTERIA_BASSA";
                    } else if (humidex < (sogliaAttivazioneLogica + isteresiAccensioneNotte)) {
                        motivoAc = "COMFORT_NOTTURNO_RAGGIUNTO";
                    } else if ((adesso - ultimoSpegnimentoNotte) < tempoMinimoPausaNotte) {
                        motivoAc = "BLOCCO_NOTTE_PAUSA_45M";
                    } else {
                        motivoAc = "PRONTO_ACCENSIONE_NIGHT_DRY";
                    }
                } else {
                    if (isPeriodoDiGrazia && usaSoloSolare && surplus < 1000 && !solareForteDaOff) {
                        motivoAc = "BLOCCO_GRAZIA_VINCOLO_SOLARE";
                    } else if (soc < socMinimoLogico && humidex < EMERGENCY_HUMIDEX_AWAY && !solareForteDaOff) {
                        motivoAc = "BLOCCO_DIURNO_BATTERIA";
                    } else if (surplusVirtuale <= 150 && humidex < EMERGENCY_HUMIDEX_AWAY && !solareForteDaOff) {
                        motivoAc = "ATTESA_SURPLUS_SOLARE";
                    } else if (humidex < sogliaAttivazioneLogica) {
                        motivoAc = "COMFORT_DIURNO_RAGGIUNTO";
                    } else {
                        motivoAc = (solareForteDaOff && soc < socMinimoLogico) ? "PRONTO_ACCENSIONE_OVERRIDE_SOLARE" : "PRONTO_ACCENSIONE_COOLING";
                    }
                }

                if (bloccoSpegnimentoEmergenza) {
                    transizionePermessa = false; 
                } else if (esSeraFasciaDinamica) {
                    if (soc >= socMinimoLogico && humidex >= sogliaAttivazioneLogica) transizionePermessa = true;
                } else if (esNotteFascia) {
                    if (soc > 75 && humidex >= (sogliaAttivazioneLogica + 1.0)) transizionePermessa = true;
                } else {
                    if ((soc >= socMinimoLogico || solareForteDaOff) && surplusVirtuale > 150) transizionePermessa = true;
                    if (humidex >= EMERGENCY_HUMIDEX_AWAY) transizionePermessa = true;
                    if (isPeriodoDiGrazia && usaSoloSolare) {
                        if (surplus < 1000 && !solareForteDaOff) transizionePermessa = false;
                    }
                }

                if (!esNotteFascia && transizionePermessa && humidex >= sogliaAttivazioneLogica) {
                    if (minMancantiAccensione === 0) {
                        statoAttuale = "COOLING_ON"; flow.set("condizionatore_stato", "COOLING_ON", "file"); global.set("ultimo_avvio", adesso, "file");
                        if (temp >= 26) comandoIR = "23"; else if (temp >= 25) comandoIR = "24"; else if (temp >= 24) comandoIR = "23"; else if (temp >= 23) comandoIR = "22"; else comandoIR = "26";
                        motivoAc = "ESECUZIONE_ACCENSIONE_DIURNA";
                    }
                } else if (esNotteFascia && soc > socMinimoLogico) {
                    let ultimoSpegnimentoNotte = flow.get("ultimo_spegnimento_notte", "file") || 0;
                    let tempoMinimoPausaNotte = 45 * 60 * 1000;
                    let isteresiAccensioneNotte = 0.5; 

                    if (humidex >= (sogliaAttivazioneLogica + isteresiAccensioneNotte)) {

                        if (
                            (adesso - ultimoSpegnimentoNotte) >= tempoMinimoPausaNotte &&
                            minMancantiAccensione === 0
                        ) {

                            // ==================================================
                            // PR-ARB.4C.2
                            // Gate SOLO per nuovo avvio OFF -> NIGHT_DRY
                            //
                            // PR OFF  -> BYPASS legacy
                            // PR ON   -> fail-closed salvo autorizzazione valida
                            //
                            // IMPORTANTE:
                            // nessuna mutazione dello stato AC prima della decisione.
                            // ==================================================

                            const PR_MAX_SNAPSHOT_AGE_MS = 120000;

                            const prGate =
                                global.get("pr_arbitration_gate");

                            let prAction = "DENY";
                            let prReason = "PR_GATE_INVALID";


                            // --------------------------------------------------
                            // Gate presente e formalmente valido
                            // --------------------------------------------------

                            if (
                                prGate &&
                                typeof prGate === "object" &&
                                prGate.schema ===
                                "domopi.predictive_reserve.arbitration_gate.v1" &&
                                typeof prGate.control_enabled === "boolean"
                            ) {

                                // ==============================================
                                // KILL SWITCH OFF
                                //
                                // BYPASS TOTALE:
                                // il codice legacy deve comportarsi esattamente
                                // come prima dell'integrazione PR.
                                // ==============================================

                                if (prGate.control_enabled === false) {

                                    prAction = "BYPASS";
                                    prReason = "PR_CONTROL_DISABLED";
                                }


                                // ==============================================
                                // PR richiesto ON
                                // ==============================================

                                else {

                                    // PR può partecipare soltanto se realmente
                                    // ACTIVE e con authority.allowed=true.
                                    if (prGate.effective_authority !== true) {

                                        prAction = "DENY";
                                        prReason = "PR_NOT_AUTHORIZED";
                                    }

                                    else {

                                        const snap =
                                            prGate.snapshot;

                                        if (
                                            !snap ||
                                            typeof snap !== "object" ||
                                            snap.schema !==
                                            "domopi.predictive_reserve.arbitration_snapshot.v1"
                                        ) {

                                            prAction = "DENY";
                                            prReason = "SNAPSHOT_INVALID";
                                        }

                                        else {

                                            // Preferiamo il timestamp della vera
                                            // Final SHADOW Decision.
                                            // Non permettiamo che un adapter
                                            // "ringiovanisca" una decisione vecchia.
                                            const sourceTs =
                                                snap.source &&
                                                Number(
                                                    snap.source
                                                        .final_decision_timestamp_ms
                                                );

                                            const snapshotTs =
                                                Number(snap.timestamp_ms);

                                            const decisionTs =
                                                Number.isFinite(sourceTs)
                                                    ? sourceTs
                                                    : snapshotTs;

                                            if (
                                                !Number.isFinite(decisionTs) ||
                                                decisionTs > adesso
                                            ) {

                                                prAction = "DENY";
                                                prReason = "SNAPSHOT_INVALID";
                                            }

                                            else if (
                                                (adesso - decisionTs) >
                                                PR_MAX_SNAPSHOT_AGE_MS
                                            ) {

                                                prAction = "DENY";
                                                prReason = "SNAPSHOT_STALE";
                                            }

                                            else if (
                                                !snap.decision ||
                                                snap.decision.valid !== true
                                            ) {

                                                prAction = "DENY";

                                                prReason =
                                                    snap.decision &&
                                                        typeof snap.decision.reason === "string"
                                                        ? snap.decision.reason
                                                        : "DECISION_NOT_READY";
                                            }

                                            else if (
                                                snap.decision
                                                    .allow_night_dry_start !== true
                                            ) {

                                                prAction = "DENY";

                                                prReason =
                                                    typeof snap.decision.reason === "string"
                                                        ? snap.decision.reason
                                                        : "ENERGY_DENY";
                                            }

                                            else {

                                                prAction = "ALLOW";
                                                prReason = "ALLOW";
                                            }
                                        }
                                    }
                                }
                            }


                            // ==================================================
                            // COMMIT NIGHT_DRY
                            //
                            // È intenzionalmente lo stesso codice legacy.
                            // Viene eseguito:
                            //
                            // - PR OFF  -> BYPASS
                            // - PR ACTIVE + decisione valida -> ALLOW
                            // ==================================================

                            if (
                                prAction === "BYPASS" ||
                                prAction === "ALLOW"
                            ) {

                                statoAttuale = "NIGHT_DRY";

                                flow.set(
                                    "condizionatore_stato",
                                    "NIGHT_DRY",
                                    "file"
                                );

                                global.set(
                                    "ultimo_avvio",
                                    adesso,
                                    "file"
                                );

                                // --- SELEZIONE DINAMICA DEL COMANDO DRY ---
                                if (temp > 27) {
                                    comandoIR = "eco26dry";
                                } else if (temp >= 26) {
                                    comandoIR = "eco25dry";
                                } else if (temp >= 25) {
                                    comandoIR = "25dry";
                                } else if (temp >= 24) {
                                    comandoIR = "24dry";
                                } else {
                                    comandoIR = "23dry";
                                }
                                // ------------------------------------------

                                if (prAction === "ALLOW") {
                                    motivoAc =
                                        "ESECUZIONE_ACCENSIONE_NOTTURNA_PR";
                                } else {
                                    motivoAc =
                                        "ESECUZIONE_ACCENSIONE_NOTTURNA";
                                }
                            }


                            // ==================================================
                            // DENY
                            //
                            // Nessuna mutazione:
                            // - statoAttuale resta OFF
                            // - condizionatore_stato non viene scritto
                            // - ultimo_avvio non viene scritto
                            // - comandoIR non viene prodotto
                            // ==================================================

                            else {

                                motivoAc =
                                    "BLOCCO_PR_" + prReason;
                            }
                        }
                    }
                }
            } 
            else {
                let richiediSpegnimento = false;
                let richiediStandby = false;

                if (!bloccoSpegnimentoEmergenza) {
                    motivoAc = `MANTENIMENTO_${statoAttuale}`;
                }

                if (statoAttuale === "COOLING_ON" || statoAttuale === "STANDBY_INVERTER") {
                    let limiteDeficitSurplus = soc > 95 ? -1500 : -300;

                    if (esSeraFasciaDinamica) {
                        if (soc > 90) limiteDeficitSurplus = -2000;      
                        else if (soc > 80) limiteDeficitSurplus = -1000; 
                        else if (soc > 70) limiteDeficitSurplus = -400;  
                        else limiteDeficitSurplus = -100;                
                    }

                    if (isPeriodoDiGrazia && usaSoloSolare) {
                        limiteDeficitSurplus = 500; 
                    }

                    let sogliaSpegnimentoComfort = 26;

                    if (isPeriodoDiGrazia && !usaSoloSolare) {
                        if (humidex > EMERGENCY_HUMIDEX_AWAY) {
                            sogliaSpegnimentoComfort = EMERGENCY_HUMIDEX_AWAY; 
                        } else {
                            richiediStandby = true; 
                        }
                    } else {
                        let ampiezzaIsteresi = 2.5; 
                        sogliaSpegnimentoComfort = sogliaAttivazioneLogica - ampiezzaIsteresi;
                    }

                    if (bloccoSpegnimentoEmergenza) {
                        richiediSpegnimento = true; 
                        flow.set("inizio_deficit_surplus", 0);
                    }
                    else if (humidex <= sogliaSpegnimentoComfort) {
                        richiediStandby = true;
                        flow.set("inizio_deficit_surplus", 0);
                        if (minMancantiSpegnimento > 0) motivoAc = "COMFORT_RAGGIUNTO_ATTESA_TIMER";
                        else motivoAc = "STANDBY_COMFORT_RAGGIUNTO";
                    }
                    else if (surplus < limiteDeficitSurplus) {
                        let inizioDeficit = flow.get("inizio_deficit_surplus") || 0;
                        if (inizioDeficit === 0) {
                            flow.set("inizio_deficit_surplus", adesso);
                            motivoAc = "DEFICIT_RILEVATO_AVVIO_TIMER";
                        } else {
                            if ((adesso - inizioDeficit) >= DEFICIT_TOLERANCE_TIME) {
                                if (soc < socMinimoLogico && !solareForteAttivo) {
                                    richiediSpegnimento = true; 
                                } else {
                                    richiediStandby = true; 
                                    motivoAc = "STANDBY_DEFICIT_SOLARE";
                                }
                            } else {
                                motivoAc = "TOLLERANZA_DEFICIT_IN_CORSO";
                            }
                        }
                    }
                    else {
                        if (flow.get("inizio_deficit_surplus")) {
                            flow.set("inizio_deficit_surplus", 0);
                        }

                        if (statoAttuale === "STANDBY_INVERTER" && humidex >= sogliaAttivazioneLogica) {
                            statoAttuale = "COOLING_ON"; 
                            flow.set("condizionatore_stato", "COOLING_ON", "file"); 
                            global.set("ultimo_avvio", adesso, "file");
                            if (temp >= 26) comandoIR = "23"; else if (temp >= 25) comandoIR = "24"; else if (temp >= 24) comandoIR = "23"; else if (temp >= 23) comandoIR = "22"; else comandoIR = "26";
                            motivoAc = "RIPRESA_COOLING_DA_STANDBY";
                        }
                    }

                    if ((soc <= socMinimoLogico && !solareForteAttivo && !bloccoSpegnimentoEmergenza) || esNotteFascia) {
                        richiediSpegnimento = true;
                        richiediStandby = false;
                    }
                }

                if (statoAttuale === "NIGHT_DRY") {
                    if (soc <= socMinimoLogico) {
                        richiediSpegnimento = true;
                        flow.set("ultimo_spegnimento_notte", adesso, "file");
                        if(minMancantiSpegnimento > 0) motivoAc = "BATTERIA_SCARICA_ATTESA_TIMER";
                    } else if (!esNotteFascia) {
                        richiediSpegnimento = true;
                    }
                }

                let eseguiSpegnimento = bloccoSpegnimentoEmergenza ? true : (richiediSpegnimento && minMancantiSpegnimento === 0);

                if (eseguiSpegnimento) {
                    statoAttuale = "OFF";
                    flow.set("condizionatore_stato", "OFF", "file");
                    global.set("ultimo_spegnimento", adesso, "file");
                    comandoIR = "OFF";
                    flow.set("inizio_deficit_surplus", 0); 
                    if (!bloccoSpegnimentoEmergenza) motivoAc = "ESECUZIONE_SPEGNIMENTO";
                } 
                else if (richiediStandby && statoAttuale !== "STANDBY_INVERTER" && minMancantiSpegnimento === 0) {
                    statoAttuale = "STANDBY_INVERTER";
                    flow.set("condizionatore_stato", "STANDBY_INVERTER", "file");
                    global.set("ultimo_spegnimento", adesso, "file");
                    comandoIR = "28"; 
                    flow.set("inizio_deficit_surplus", 0);
                    motivoAc = "ESECUZIONE_STANDBY_INVERTER";
                }
            }
        }
    }

    // ==================================================
    // B.3 LOGICA VMC 
    // ==================================================
    if (MODALITA_STAGIONE === "ESTATE") {
        if (tempEsterna < (temp - 1.5)) {
            velocitaVmc = 3;
            motivoVmc = "FREE_COOLING_ATTIVO";
        }
        else if (tempEsterna >= (temp + 0.5)) {
            velocitaVmc = 1;
            motivoVmc = "SCUDO_TERMICO_ATTIVO";
        }
        else {
            if (humidex >= 30 && humidexEsterno < (humidex + 2.0)) {
                velocitaVmc = 3;
                motivoVmc = "ESTRAZIONE_UMIDITA_ALTA";
            }
            else if (humidex >= 27 && humidexEsterno < (humidex + 2.0)) {
                velocitaVmc = 2;
                motivoVmc = "ESTRAZIONE_UMIDITA_MEDIA";
            }
            else {
                velocitaVmc = 1;
                motivoVmc = "RICAMBIO_ARIA_BASE";
            }
        }
    }
    else {
        let urInterna = esNotteFascia ? flow.get("umidita_bedroom") : flow.get("umidita_living");
        if (urInterna === undefined) urInterna = 50;

        if (urInterna >= 65) { velocitaVmc = 3; motivoVmc = "ANTI_CONDENSA_MASSIMO"; }
        else if (urInterna >= 55) { velocitaVmc = 2; motivoVmc = "ANTI_CONDENSA_MEDIO"; }
        else if (tempEsterna < (temp - 5.0) && urInterna < 50) { velocitaVmc = 1; motivoVmc = "SCUDO_TERMICO_INVERNALE_ATTIVO"; }
        else { velocitaVmc = 1; motivoVmc = "COMFORT_INVERNALE_BASE"; }
    }

    if (esNotteFascia && velocitaVmc > VMC_MAX_NOTTE) { velocitaVmc = VMC_MAX_NOTTE; motivoVmc = motivoVmc + "_LIMITATO_NOTTE"; }
}

let currentTime = Date.now();
let lastVmcChangeTime = flow.get('vmc_ultimo_cambio_ms') || 0;
let lastVmcSpeed = flow.get("vmc_velocita_inviata") || velocitaVmc; 
let cooldownMs = 5 * 60 * 1000; 

if (velocitaVmc !== lastVmcSpeed) {
    if (currentTime - lastVmcChangeTime < cooldownMs) {
        velocitaVmc = lastVmcSpeed;
        motivoVmc = "BLOCCO_ANTIRIMBALZO_ATTIVO";
    } else {
        flow.set('vmc_ultimo_cambio_ms', currentTime);
    }
}

flow.set("vmc_fanspeed", velocitaVmc);

if (!aiAbilitata) {
    flow.set("ac_log_temp", 0, "file");
    flow.set("ac_log_mode", "OFF", "file");
} else if (comandoIR) {
    let estrazioneTesto = comandoIR.match(/\d+/);
    let targetImpostato = estrazioneTesto ? parseFloat(estrazioneTesto[0]) : 0;

    if (comandoIR === "OFF" || comandoIR === "stop") { 
        flow.set("ac_log_temp", 0, "file"); flow.set("ac_log_mode", "OFF", "file"); 
    }
    else if (comandoIR.includes("dry")) { 
        flow.set("ac_log_temp", targetImpostato || 25.0, "file"); flow.set("ac_log_mode", "Deumidificazione", "file"); 
    }
    else if (comandoIR.includes("heat")) { 
        flow.set("ac_log_temp", targetImpostato || 19.0, "file"); flow.set("ac_log_mode", "Riscaldamento", "file"); 
    }
    else { 
        flow.set("ac_log_temp", targetImpostato || 24.0, "file"); flow.set("ac_log_mode", "Raffrescamento", "file"); 
    }
} else if (statoAttuale === "OFF") {
    flow.set("ac_log_temp", 0, "file"); flow.set("ac_log_mode", "OFF", "file");
}

let tempImpostata = flow.get("ac_log_temp", "file") || 0;
let modalitaAria = flow.get("ac_log_mode", "file") || "OFF";

// --- DATI PER L'APP ANDROID (UI E WIDGET) ---
let datiAndroid = {
    timestamp: adesso,
    data_ora_formattata: dataOraFormattata,
    stagione_attiva: MODALITA_STAGIONE,
    metriche_elettriche: {
        produzione_fv_w: prod, 
        consumo_casa_w: cons, 
        surplus_w: surplus,
        grid_power_w: gridPowerRaw,
        grid_import_w: gridImportW,
        grid_export_w: gridExportW,
        battery_power_w: batteryPowerRaw,
        battery_charge_w: batteryChargeW,
        battery_discharge_w: batteryDischargeW,
        powerwall_soc_percent: soc, 
        consumo_ac_w: acPower, 
        consumo_medio_storico_fascia_w: consumoStoricoAttuale
    },
    metriche_ambientali: {
        temp_cameraMatrimoniale: temp_cameraMatrimoniale, temperatura_c: temp,
        humidex: humidex, humidex_living: hGiorno, humidex_bedroom: hNotte,
        altitudine_sole: sunAltitude
    },
    logica_controllo: {
        vmc_portata_stimata_m3h: vmc_portata[velocitaVmc],
        stanza_rilevamento_vmc: esNotteFascia ? "BEDROOM" : "LIVING",
        soglia_attivazione_applicata: sogliaAttivazioneLogica,
        soc_minimo_applied: socMinimoLogico,
        tempo_mancante_anticiclo_minuti: tempoMancanteMinuti,
        previsione_solare_domani_kwh: kwhDomani, previsione_solare_data: dataDomani,
        previsione_ricarica_batteria_percent: percentualeRicaricaPrevista, 
        kwh_stimati_in_batteria: parseFloat(kwhDestinatiAllaBatteria.toFixed(1)),
        blocco_emergenza_attivo: bloccoSpegnimentoEmergenza,
        cuscinetto_sicurezza_kwh: parseFloat(cuscinettoSicurezzaKwh.toFixed(2)),
        cuscinetto_richiesto_kwh: parseFloat(cuscinettoMinimoRichiesto.toFixed(2))
    },
    stato_condizionatore: {
        stato_attuale: statoAttuale,
        motivo_logica: motivoAc,
        temperatura_impostata_c: tempImpostata,
        modalita_aria: modalitaAria
    },
    stato_vmc: {
        velocita_attuale: velocitaVmc, motivo_logica: motivoVmc,
        humidex_esterno: humidexEsterno, temperatura_esterna_c: tempEsterna
    }
};

// --- LOGGING STRUTTURATO PER STORICO E GRAFANA ---
let msgLog = null;
let precedenteStatoAC = flow.get("log_ultimo_stato_ac") || "OFF";
let precedenteVelocitaVMC = flow.get("log_ultima_vmc") || 1;
let precedenteMotivoAC = flow.get("log_ultimo_motivo_ac") || "";

if (comandoIR || statoAttuale !== precedenteStatoAC || velocitaVmc !== precedenteVelocitaVMC || motivoAc !== precedenteMotivoAC) {
    msgLog = {
        payload: {
            timestamp: adesso, data_ora: dataOraFormattata, evento: "CAMBIO_STATO_SISTEMA",
            dettaglio_comandi: {
                comando_ir_inviato: comandoIR || "NESSUNO", stato_ac_precedente: precedenteStatoAC, stato_ac_attuale: statoAttuale,
                vmc_velocita_precedente: precedenteVelocitaVMC, vmc_velocita_attuale: velocitaVmc, motivo_logica: motivoVmc,
                humidex_esterno: humidexEsterno, temperatura_esterna_c: tempEsterna, modalita_aria: modalitaAria, temperatura_impostata_c: tempImpostata
            },
            condizioni_ambientali: { 
                humidex_living: hGiorno, humidex_bedroom: hNotte, temperatura_c: temp, temp_cameraMatrimoniale: temp_cameraMatrimoniale, 
                humidex: humidex, stanza_rilevamento: esNotteFascia ? "BEDROOM" : "LIVING", altitudine_sole: sunAltitude 
            },
            stato_energia: { 
                produzione_w: prod, consumo_w: cons, surplus_w: surplus, powerwall_soc_percent: soc, consumo_ac_w: acPower, soc_minimo_applied: socMinimoLogico,
                grid_import_w: gridImportW, grid_export_w: gridExportW, battery_charge_w: batteryChargeW, battery_discharge_w: batteryDischargeW
            },
            logica_controllo: { 
                previsione_solare_domani_kwh: kwhDomani, previsione_solare_data: dataDomani, previsione_ricarica_batteria_percent: percentualeRicaricaPrevista, 
                kwh_stimati_in_batteria: parseFloat(kwhDestinatiAllaBatteria.toFixed(1)), motivo_ac: motivoAc,
                blocco_emergenza_attivo: bloccoSpegnimentoEmergenza, cuscinetto_sicurezza_kwh: parseFloat(cuscinettoSicurezzaKwh.toFixed(2)),
                cuscinetto_richiesto_kwh: parseFloat(cuscinettoMinimoRichiesto.toFixed(2))
            }
        },
        topic: "casa/clima/log_eventi"
    };
    flow.set("log_ultimo_stato_ac", statoAttuale);
    flow.set("log_ultima_vmc", velocitaVmc);
    flow.set("log_ultimo_motivo_ac", motivoAc);
}

let msgBroadlink = comandoIR ? { payload: comandoIR, topic: "broadlink/cmd" } : null;
let baseTopic = global.get("app_base_topic", "file") || "zara/android/domotica";
let msgAndroid = { payload: datiAndroid, topic: `${baseTopic}/casa/clima/stato_completo` };

let ultimaVelocitaInviata = flow.get("vmc_velocita_inviata") || -1;
let msgVmc = null; 

if (velocitaVmc !== ultimaVelocitaInviata) {
    msgVmc = { topic: "/esp8266/brink/fanspeed", payload: velocitaVmc };
    flow.set("vmc_velocita_inviata", velocitaVmc);
}

return [msgBroadlink, msgAndroid, msgVmc, msgLog, msgHealth];

// ==================================================
// 0. CONTROLLO DI COERENZA (SANITY CHECK) & FAIL-SAFE
// ==================================================
// --- CONTROLLO DI COERENZA E STATO PERSISTENTE ---
let variabiliCritiche = [
    { nome: "user_min_run_time", defaultVal: 15 },
    { nome: "user_min_off_time", defaultVal: 20 },
    { nome: "user_deficit_tolerance_time", defaultVal: 40 },
    { nome: "user_vmc_max_notte", defaultVal: 2 },
    { nome: "user_target_humidex_estate", defaultVal: 29.0 },
    { nome: "user_emergency_humidex_away", defaultVal: 33.0 },
    { nome: "grace_mode_solar", defaultVal: false }
];

let mancanti = [];

variabiliCritiche.forEach(v => {
    let val = global.get(v.nome, "file");
    if (val === undefined) {
        mancanti.push(v.nome);
        global.set(v.nome, v.defaultVal, "file");
    }
});

let msgHealth = {
    topic: "casa/clima/system_health/stat"
};

if (mancanti.length > 0) {
    node.warn("STATO SISTEMA INCONSISTENTE: Parametri globali mancanti su file -> " + mancanti.join(", "));
    msgHealth.payload = {
        stato: "INCONSISTENTE",
        motivo: "Mancanza di parametri globali persistenti, ripristinati i default",
        elementi_mancanti: mancanti,
        timestamp: Date.now()
    };
} else {
    msgHealth.payload = {
        stato: "NORMALE",
        timestamp: Date.now()
    };
}

// ==================================================
// 1. MEMORIZZAZIONE DEI DATI IN INGRESSO
// ==================================================
if (msg.topic === "system/boot") {
    // Boot sync
}
else if (msg.topic === "TeslaPowerwall/solar_instant_power") {
    flow.set("produzione", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/load_instant_power") {
    flow.set("consumo", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/site_instant_power") {
    flow.set("grid_power", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/battery_instant_power") {
    flow.set("battery_power", parseFloat(msg.payload), "file");
}
else if (msg.topic === "emon/planetary/altitude") {
    flow.set("sun_altitude", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/SOE") {
    let rawSoc = parseFloat(msg.payload);
    let lastValidSoc = flow.get("powerwall_soc", "file");

    if (lastValidSoc === undefined) {
        flow.set("powerwall_soc", rawSoc, "file");
    } else {
        let delta = Math.abs(rawSoc - lastValidSoc);
        if (delta <= 3.0) {
            flow.set("powerwall_soc", rawSoc, "file");
            flow.set("soc_glitch_count", 0, "file"); 
        } else {
            let glitchCount = flow.get("soc_glitch_count", "file") || 0;
            glitchCount++;
            if (glitchCount >= 5) {
                flow.set("powerwall_soc", rawSoc, "file");
                flow.set("soc_glitch_count", 0, "file");
            } else {
                flow.set("soc_glitch_count", glitchCount, "file");
            }
        }
    }
}
else if (msg.topic === "emon/emonth5/temperature_calibrated") {
    flow.set("temperatura", parseFloat(msg.payload),"file");
}
else if (msg.topic === "zara/domotics/LivingHumidex") {
    flow.set("humidex_giorno", parseFloat(msg.payload), "file");
}
else if (msg.topic === "zara/domotics/BedroomHumidex") {
    flow.set("humidex_notte", parseFloat(msg.payload), "file");
}
else if (msg.topic === "zigbee2mqtt/Sonoff AirGuard TH esterno cucina") {
    flow.set("temp_esterno", parseFloat(msg.payload.temperature));
    flow.set("umidita_esterno", parseFloat(msg.payload.humidity));
}
else if (msg.topic === "emon/cameraMatrimoniale/temperature") {
    flow.set("temp_cameraMatrimoniale", parseFloat(msg.payload));
}
else if (msg.topic === "emon/AC/emeter_power") {
    flow.set("ac_power", Math.abs(parseFloat(msg.payload)), "file"); 
}

let meseAttuale = new Date().getMonth();
let MODALITA_STAGIONE = (meseAttuale >= 4 && meseAttuale <= 8) ? "ESTATE" : "INVERNO";

let tempEsterna = flow.get("temp_esterno");
let umiditaEsterna = flow.get("umidita_esterno");

if (tempEsterna === undefined || umiditaEsterna === undefined) {
    tempEsterna = (MODALITA_STAGIONE === "ESTATE") ? 24 : 8;
    umiditaEsterna = 60;
}

let aEst = 17.27;
let bEst = 237.7;
let alphaEst = ((aEst * tempEsterna) / (bEst + tempEsterna)) + Math.log(umiditaEsterna / 100);
let dewPointEst = (bEst * alphaEst) / (aEst - alphaEst);
let eEst = 6.11 * Math.exp(5417.7530 * ((1 / 273.15) - (1 / (273.15 + dewPointEst))));
let humidexEsterno = parseFloat((tempEsterna + (5 / 9) * (eEst - 10)).toFixed(1));

let adesso = Date.now();
let statoAttuale = flow.get("condizionatore_stato", "file") || "OFF";

let ultimoAvvio = global.get("ultimo_avvio", "file") || (adesso - 40 * 60 * 1000);
let ultimoSpegnimento = global.get("ultimo_spegnimento", "file") || (adesso - 40 * 60 * 1000);

const MIN_RUN_MINUTI = parseFloat(global.get("user_min_run_time", "file")) || 15;
const MIN_OFF_MINUTI = parseFloat(global.get("user_min_off_time", "file")) || 15;
const DEFICIT_TOLERANCE_MINUTI = parseFloat(global.get("user_deficit_tolerance_time", "file")) || 10; 
const VMC_MAX_NOTTE = parseInt(global.get("user_vmc_max_notte", "file")) || 2;
const TARGET_HUMIDEX_ESTATE = parseFloat(global.get("user_target_humidex_estate", "file")) || 29;
const EMERGENCY_HUMIDEX_AWAY = parseFloat(global.get("user_emergency_humidex_away", "file")) || 33.0;

const MIN_RUN_TIME = MIN_RUN_MINUTI * 60 * 1000;
const MIN_OFF_TIME = MIN_OFF_MINUTI * 60 * 1000;
const DEFICIT_TOLERANCE_TIME = DEFICIT_TOLERANCE_MINUTI * 60 * 1000; 

let tempoPassatoDallAccensione = adesso - ultimoAvvio;
let tempoPassatoDalloSpegnimento = adesso - ultimoSpegnimento;

let minMancantiSpegnimento = tempoPassatoDallAccensione < MIN_RUN_TIME ? Math.ceil((MIN_RUN_TIME - tempoPassatoDallAccensione) / 60000) : 0;
let minMancantiAccensione = tempoPassatoDalloSpegnimento < MIN_OFF_TIME ? Math.ceil((MIN_OFF_TIME - tempoPassatoDalloSpegnimento) / 60000) : 0;
let tempoMancanteMinuti = (statoAttuale === "OFF") ? minMancantiAccensione : minMancantiSpegnimento;

// ==================================================
// 2. RECUPERO DERIVAZIONI ENERGETICHE E ASTRONOMICHE
// ==================================================
let prod = flow.get("produzione", "file") || 0;
let cons = flow.get("consumo", "file") || 0;
let soc = (flow.get("powerwall_soc", "file") !== undefined) ? flow.get("powerwall_soc", "file") : 0;
let temp = flow.get("temperatura", "file") || 19;
let hGiorno = flow.get("humidex_giorno", "file") || 0;
let hNotte = flow.get("humidex_notte", "file") || 0;
let temp_cameraMatrimoniale = flow.get("temp_cameraMatrimoniale") || 0;
let acPower = flow.get("ac_power", "file") || 0;

let gridPowerRaw = flow.get("grid_power", "file") || 0;
let batteryPowerRaw = flow.get("battery_power", "file") || 0;
let sunAltitude = flow.get("sun_altitude", "file"); 
if (sunAltitude === undefined) sunAltitude = 90; 

let gridImportW = Math.max(gridPowerRaw, 0);
let gridExportW = Math.max(-gridPowerRaw, 0);
let batteryDischargeW = Math.max(batteryPowerRaw, 0);
let batteryChargeW = Math.max(-batteryPowerRaw, 0);

let vmc_portata = [0, 50, 130, 160, 300];
let oraAttuale = new Date().getHours();
let surplus = prod - cons;

let kwhDomani = flow.get("previsione_kwh_domani") || 12;
let dataDomani = flow.get("previsione_data_domani") || "N/A";
let tutteMedie = flow.get("tutte_medie_storiche", "file") || global.get("tutte_medie_storiche", "file") || { ESTATE: { GIORNO: 600, NOTTE: 400 }, INVERNO: { GIORNO: 800, NOTTE: 500 } };

let dataOraFormattata = new Intl.DateTimeFormat('it-IT', {
    timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false
}).format(new Date(adesso));

let esNotteFascia = (oraAttuale >= 22 || oraAttuale < 8);
let humidex = esNotteFascia ? hNotte : hGiorno;
if (humidex === 0) humidex = (hGiorno !== 0) ? hGiorno : hNotte;

const CAPACITA_BATTERIA_KWH = 13.5;
let consumoDiurnoStimatoKwh = (tutteMedie[MODALITA_STAGIONE]["GIORNO"] * 12) / 1000;
if (isNaN(consumoDiurnoStimatoKwh) || consumoDiurnoStimatoKwh < 3) consumoDiurnoStimatoKwh = 7.5;

let energiaDisponibilePerBatteriaKwh = (kwhDomani - consumoDiurnoStimatoKwh) * 0.95;
if (energiaDisponibilePerBatteriaKwh < 0) energiaDisponibilePerBatteriaKwh = 0;

let socStimatoMattino = soc - 15;
if (socStimatoMattino < 0) socStimatoMattino = 0;
if (socStimatoMattino > 100) socStimatoMattino = 100; 

let capacitaVuotaKwh = CAPACITA_BATTERIA_KWH * (1 - (socStimatoMattino / 100));
let kwhDestinatiAllaBatteria = 0;
let percentualeRicaricaPrevista = 0;

if (energiaDisponibilePerBatteriaKwh >= capacitaVuotaKwh) {
    kwhDestinatiAllaBatteria = capacitaVuotaKwh;
    percentualeRicaricaPrevista = 100;
} else {
    kwhDestinatiAllaBatteria = energiaDisponibilePerBatteriaKwh;
    let ricaricaAggiuntivaPercentuale = (energiaDisponibilePerBatteriaKwh / CAPACITA_BATTERIA_KWH) * 100;
    percentualeRicaricaPrevista = Math.round(socStimatoMattino + ricaricaAggiuntivaPercentuale);
}

if (percentualeRicaricaPrevista > 100) percentualeRicaricaPrevista = 100;
if (percentualeRicaricaPrevista < 0) percentualeRicaricaPrevista = 0;

let comandoIR = null;
let sogliaAttivazioneLogica = 0;
let socMinimoLogico = 0;
let consumoStoricoAttuale = tutteMedie[MODALITA_STAGIONE][esNotteFascia ? "NOTTE" : "GIORNO"];

// --- Inizializzazione Variabili per Log e UI ---
let bloccoSpegnimentoEmergenza = false; 
let energiaDisponibileKwh = 0;
let consumoNotteStimatoKwh = 0;
let cuscinettoSicurezzaKwh = 0;
let cuscinettoMinimoRichiesto = 0;

// ==================================================
// 3. MASTER SWITCH E LOGICA INTEGRATA
// ==================================================
let aiAbilitata = flow.get("AI_climate_enabling", "file");
if (aiAbilitata === undefined) {
    aiAbilitata = true;
    flow.set("AI_climate_enabling", true, "file");
}
let systemWasDisabled = flow.get("system_was_disabled") || false;

let velocitaVmc = 1;
let motivoVmc = "STANDBY_MINIMO";
let motivoAc = "ANALISI_IN_CORSO";

if (!aiAbilitata) {
    if (!systemWasDisabled) {
        comandoIR = "OFF"; 
        statoAttuale = "OFF";
        flow.set("condizionatore_stato", "OFF", "file");
        flow.set("system_was_disabled", true);
        global.set("ultimo_spegnimento", adesso, "file");
    } else {
        statoAttuale = "OFF";
    }
    velocitaVmc = 1;
    motivoVmc = "SISTEMA_DISABILITATO";
    motivoAc = "SISTEMA_DISABILITATO_DA_UTENTE";
    tempoMancanteMinuti = 0;

} else {
    if (systemWasDisabled) {
        flow.set("system_was_disabled", false);
    }

    let bypassRoutine = false;

    if (statoAttuale !== "OFF" && acPower >= 10) {
        flow.set("tentativi_riavvio_ac", 0);
    }

    if (statoAttuale === "OFF" && acPower > 30 && (adesso - ultimoSpegnimento > 3 * 60 * 1000)) {
        comandoIR = "OFF";
        global.set("ultimo_spegnimento", adesso, "file"); 
        ultimoSpegnimento = adesso;                      
        motivoAc = "WATCHDOG_FALSO_OFF";
        bypassRoutine = true; 
    }
    else if (statoAttuale !== "OFF" && statoAttuale !== "STANDBY_INVERTER" && acPower < 10 && (adesso - ultimoAvvio > 6 * 60 * 1000)) {
        let tentativi = flow.get("tentativi_riavvio_ac") || 0;

        if (tentativi < 3) {
            tentativi++;
            flow.set("tentativi_riavvio_ac", tentativi);

            statoAttuale = "OFF";
            flow.set("condizionatore_stato", "OFF", "file");
            global.set("ultimo_spegnimento", adesso - MIN_OFF_TIME - 1000, "file");
            tempoMancanteMinuti = 0;
            minMancantiAccensione = 0;
            motivoAc = "WATCHDOG_TENTATIVO_RIAVVIO_" + tentativi;
        } else {
            aiAbilitata = false;
            flow.set("AI_climate_enabling", false, "file");
            flow.set("tentativi_riavvio_ac", 0);

            comandoIR = "OFF"; 
            statoAttuale = "OFF";
            flow.set("condizionatore_stato", "OFF", "file");
            global.set("ultimo_spegnimento", adesso, "file");
            motivoAc = "WATCHDOG_SOSPENSIONE_SISTEMA_GUASTO";
            bypassRoutine = true;
        }
    }

    if (!bypassRoutine && aiAbilitata) {
        if (MODALITA_STAGIONE === "INVERNO") {
            sogliaAttivazioneLogica = esNotteFascia ? 17.0 : 19.0;
            socMinimoLogico = esNotteFascia ? (kwhDomani >= 22 && consumoStoricoAttuale < 700 ? 25 : (kwhDomani <= 8 || consumoStoricoAttuale > 1000 ? 60 : 40)) : 0;
            motivoAc = "LOGICA_INVERNALE_ATTIVA";

            if (statoAttuale === "OFF") {
                if (!esNotteFascia && surplus > (consumoStoricoAttuale * 0.8) && temp < 19.0) {
                    if (minMancantiAccensione === 0) {
                        statoAttuale = "HEAT_DIURNO"; flow.set("condizionatore_stato", "HEAT_DIURNO", "file"); global.set("ultimo_avvio", adesso, "file"); comandoIR = "eco19heat";
                    }
                }
                else if (esNotteFascia && temp < 17.0 && soc > socMinimoLogico) {
                    if (minMancantiAccensione === 0) {
                        statoAttuale = "HEAT_SICUREZZA_NOTTE"; flow.set("condizionatore_stato", "HEAT_SICUREZZA_NOTTE", "file"); global.set("ultimo_avvio", adesso, "file"); comandoIR = "eco17heat";
                    }
                }
            } else {
                let richiediSpegnimentoInverno = false;
                if (statoAttuale === "HEAT_DIURNO" && (esNotteFascia || surplus < -150 || temp >= 19.5)) richiediSpegnimentoInverno = true;
                if (statoAttuale === "HEAT_SICUREZZA_NOTTE" && (!esNotteFascia || temp >= 17.5 || soc <= socMinimoLogico)) richiediSpegnimentoInverno = true;

                if (richiediSpegnimentoInverno && minMancantiSpegnimento === 0) {
                    statoAttuale = "OFF"; flow.set("condizionatore_stato", "OFF", "file"); global.set("ultimo_spegnimento", adesso, "file"); comandoIR = "OFF";
                }
            }
        }
        else if (MODALITA_STAGIONE === "ESTATE") {
            sogliaAttivazioneLogica = TARGET_HUMIDEX_ESTATE;

            let esSeraFasciaDinamica = (oraAttuale >= 15 && oraAttuale < 22 && sunAltitude <= 20);

            if (esNotteFascia) {
                socMinimoLogico = (kwhDomani >= 28 && consumoStoricoAttuale < 450 ? 20 : (kwhDomani <= 12 ? 55 : 35));
            } else if (esSeraFasciaDinamica) {

                energiaDisponibileKwh = (soc / 100) * CAPACITA_BATTERIA_KWH;
                let oreAllAlba = (8 + 24 - oraAttuale) % 24; 
                consumoNotteStimatoKwh = (tutteMedie["ESTATE"]["NOTTE"] * oreAllAlba) / 1000;
                cuscinettoSicurezzaKwh = energiaDisponibileKwh - consumoNotteStimatoKwh;

                cuscinettoMinimoRichiesto = 1.0; 
                if (percentualeRicaricaPrevista < 95) {
                    let deficitRicaricaPct = 95 - percentualeRicaricaPrevista;
                    cuscinettoMinimoRichiesto += (deficitRicaricaPct * 0.05);
                }

                if (batteryDischargeW > 2500) {
                    socMinimoLogico = 100; 
                    bloccoSpegnimentoEmergenza = true;
                    motivoAc = `PEAK_SHAVING_ATTIVO (Scarica: ${batteryDischargeW}W)`;
                } 
                else if (cuscinettoSicurezzaKwh < cuscinettoMinimoRichiesto) {
                    socMinimoLogico = 100; 
                    bloccoSpegnimentoEmergenza = true;
                    motivoAc = `SOPRAVVIVENZA_NOTTE_ATTIVA (Cusc: ${cuscinettoSicurezzaKwh.toFixed(1)} < Riq: ${cuscinettoMinimoRichiesto.toFixed(1)}kWh)`;
                } 
                else {
                    socMinimoLogico = 45; 
                }
            } else {
                socMinimoLogico = (global.get("grace_mode_solar", "file") === true) ? 85 : 35; 
            }

            let gracePeriodStr = global.get("grace_period_time_range", "file") || "8-16";
            let graceParts = gracePeriodStr.split("-");
            let graceStart = parseInt(graceParts[0]) || 8;
            let graceEnd = parseInt(graceParts[1]) || 16;

            let isPeriodoDiGrazia = (oraAttuale >= graceStart && oraAttuale < graceEnd);
            let usaSoloSolare = global.get("grace_mode_solar", "file") === true; 

            if (isPeriodoDiGrazia) {
                if (!usaSoloSolare) {
                    sogliaAttivazioneLogica = EMERGENCY_HUMIDEX_AWAY;
                }
            }

            let surplusVirtuale = (statoAttuale === "OFF") ? (surplus - 700) : surplus;
            let solareForteDaOff = (!esNotteFascia && percentualeRicaricaPrevista >= 90 && surplusVirtuale > 500);
            let solareForteAttivo = (!esNotteFascia && percentualeRicaricaPrevista >= 90 && surplus > 300);

            if (statoAttuale === "OFF") {
                let transizionePermessa = false;

                if (minMancantiAccensione > 0) {
                    motivoAc = "BLOCCO_TIMER_ANTICICLO_OFF";
                } else if (bloccoSpegnimentoEmergenza) {
                    // Mantiene il divieto e il motivo impostato dai controlli di sicurezza
                } else if (esNotteFascia) {
                    let ultimoSpegnimentoNotte = flow.get("ultimo_spegnimento_notte", "file") || 0;
                    let tempoMinimoPausaNotte = 45 * 60 * 1000;
                    let isteresiAccensioneNotte = 0.5;

                    if (soc <= socMinimoLogico) {
                        motivoAc = "BLOCCO_NOTTE_BATTERIA_BASSA";
                    } else if (humidex < (sogliaAttivazioneLogica + isteresiAccensioneNotte)) {
                        motivoAc = "COMFORT_NOTTURNO_RAGGIUNTO";
                    } else if ((adesso - ultimoSpegnimentoNotte) < tempoMinimoPausaNotte) {
                        motivoAc = "BLOCCO_NOTTE_PAUSA_45M";
                    } else {
                        motivoAc = "PRONTO_ACCENSIONE_NIGHT_DRY";
                    }
                } else {
                    if (isPeriodoDiGrazia && usaSoloSolare && surplus < 1000 && !solareForteDaOff) {
                        motivoAc = "BLOCCO_GRAZIA_VINCOLO_SOLARE";
                    } else if (soc < socMinimoLogico && humidex < EMERGENCY_HUMIDEX_AWAY && !solareForteDaOff) {
                        motivoAc = "BLOCCO_DIURNO_BATTERIA";
                    } else if (surplusVirtuale <= 150 && humidex < EMERGENCY_HUMIDEX_AWAY && !solareForteDaOff) {
                        motivoAc = "ATTESA_SURPLUS_SOLARE";
                    } else if (humidex < sogliaAttivazioneLogica) {
                        motivoAc = "COMFORT_DIURNO_RAGGIUNTO";
                    } else {
                        motivoAc = (solareForteDaOff && soc < socMinimoLogico) ? "PRONTO_ACCENSIONE_OVERRIDE_SOLARE" : "PRONTO_ACCENSIONE_COOLING";
                    }
                }

                if (bloccoSpegnimentoEmergenza) {
                    transizionePermessa = false; 
                } else if (esSeraFasciaDinamica) {
                    if (soc >= socMinimoLogico && humidex >= sogliaAttivazioneLogica) transizionePermessa = true;
                } else if (esNotteFascia) {
                    if (soc > 75 && humidex >= (sogliaAttivazioneLogica + 1.0)) transizionePermessa = true;
                } else {
                    if ((soc >= socMinimoLogico || solareForteDaOff) && surplusVirtuale > 150) transizionePermessa = true;
                    if (humidex >= EMERGENCY_HUMIDEX_AWAY) transizionePermessa = true;
                    if (isPeriodoDiGrazia && usaSoloSolare) {
                        if (surplus < 1000 && !solareForteDaOff) transizionePermessa = false;
                    }
                }

                if (!esNotteFascia && transizionePermessa && humidex >= sogliaAttivazioneLogica) {
                    if (minMancantiAccensione === 0) {
                        statoAttuale = "COOLING_ON"; flow.set("condizionatore_stato", "COOLING_ON", "file"); global.set("ultimo_avvio", adesso, "file");
                        if (temp >= 26) comandoIR = "23"; else if (temp >= 25) comandoIR = "24"; else if (temp >= 24) comandoIR = "23"; else if (temp >= 23) comandoIR = "22"; else comandoIR = "26";
                        motivoAc = "ESECUZIONE_ACCENSIONE_DIURNA";
                    }
                } else if (esNotteFascia && soc > socMinimoLogico) {
                    let ultimoSpegnimentoNotte = flow.get("ultimo_spegnimento_notte", "file") || 0;
                    let tempoMinimoPausaNotte = 45 * 60 * 1000;
                    let isteresiAccensioneNotte = 0.5; 

                    if (humidex >= (sogliaAttivazioneLogica + isteresiAccensioneNotte)) {

                        if (
                            (adesso - ultimoSpegnimentoNotte) >= tempoMinimoPausaNotte &&
                            minMancantiAccensione === 0
                        ) {
                            // ==================================================
                            // PR-ACTIVE.2B.5
                            // PRESELEZIONE COMANDO CANDIDATO NIGHT_DRY
                            //
                            // Calcolo puro:
                            // - nessun comando emesso
                            // - nessuna mutazione dello stato AC
                            // - nessuna scrittura flow/global
                            // - non concede authority
                            // ==================================================

                            let candidateCommandIR = null;

                            if (temp > 27) {
                                candidateCommandIR = "eco26dry";
                            } else if (temp >= 26) {
                                candidateCommandIR = "eco25dry";
                            } else if (temp >= 25) {
                                candidateCommandIR = "25dry";
                            } else if (temp >= 24) {
                                candidateCommandIR = "24dry";
                            } else {
                                candidateCommandIR = "23dry";
                            }
/*
                            node.warn(
                                "PR-ACTIVE.2B.5 candidateCommandIR=" +
                                candidateCommandIR +
                                " temp=" +
                                temp
                            );
*/
                            // ==================================================
                            // PR-ARB.4C.2
                            // Gate SOLO per nuovo avvio OFF -> NIGHT_DRY
                            //
                            // PR OFF  -> BYPASS legacy
                            // PR ON   -> fail-closed salvo autorizzazione valida
                            //
                            // IMPORTANTE:
                            // nessuna mutazione dello stato AC prima della decisione.
                            // ==================================================

                            const PR_MAX_SNAPSHOT_AGE_MS = 120000;

                            const prGate =
                                global.get("pr_arbitration_gate");

                            let prAction = "DENY";
                            let prReason = "PR_GATE_INVALID";


                            // --------------------------------------------------
                            // Gate presente e formalmente valido
                            // --------------------------------------------------

                            if (
                                prGate &&
                                typeof prGate === "object" &&
                                prGate.schema ===
                                "domopi.predictive_reserve.arbitration_gate.v1" &&
                                typeof prGate.control_enabled === "boolean"
                            ) {

                                // ==============================================
                                // KILL SWITCH OFF
                                //
                                // BYPASS TOTALE:
                                // il codice legacy deve comportarsi esattamente
                                // come prima dell'integrazione PR.
                                // ==============================================

                                if (prGate.control_enabled === false) {

                                    prAction = "BYPASS";
                                    prReason = "PR_CONTROL_DISABLED";
                                }


                                // ==============================================
                                // PR richiesto ON
                                // ==============================================

                                else {

                                    // PR può partecipare soltanto se realmente
                                    // ACTIVE e con authority.allowed=true.
                                    if (prGate.effective_authority !== true) {

                                        prAction = "DENY";
                                        prReason = "PR_NOT_AUTHORIZED";
                                    }

                                    // ==================================================
                                    // PR-ACTIVE.2B.6
                                    // QUALIFICAZIONE DEL REGIME CANDIDATO
                                    //
                                    // La qualification è proprietà del PR Shared Gate.
                                    // Il consumer verifica il comando che sta realmente
                                    // per proporre, senza modificare lo stato AC.
                                    // ==================================================

                                    else if (
                                        !prGate.active_regimes ||
                                        typeof prGate.active_regimes !== "object" ||
                                        !prGate.active_regimes[candidateCommandIR] ||
                                        prGate.active_regimes[candidateCommandIR].qualified !== true
                                    ) {

                                        prAction = "DENY";
                                        prReason = "COMMAND_REGIME_NOT_QUALIFIED";
                                    }

                                    else {

                                        const snap =
                                            prGate.snapshot;

                                        if (
                                            !snap ||
                                            typeof snap !== "object" ||
                                            snap.schema !==
                                            "domopi.predictive_reserve.arbitration_snapshot.v1"
                                        ) {

                                            prAction = "DENY";
                                            prReason = "SNAPSHOT_INVALID";
                                        }

                                        else {

                                            // Preferiamo il timestamp della vera
                                            // Final SHADOW Decision.
                                            // Non permettiamo che un adapter
                                            // "ringiovanisca" una decisione vecchia.
                                            const sourceTs =
                                                snap.source &&
                                                Number(
                                                    snap.source
                                                        .final_decision_timestamp_ms
                                                );

                                            const snapshotTs =
                                                Number(snap.timestamp_ms);

                                            const decisionTs =
                                                Number.isFinite(sourceTs)
                                                    ? sourceTs
                                                    : snapshotTs;

                                            if (
                                                !Number.isFinite(decisionTs) ||
                                                decisionTs > adesso
                                            ) {

                                                prAction = "DENY";
                                                prReason = "SNAPSHOT_INVALID";
                                            }

                                            else if (
                                                (adesso - decisionTs) >
                                                PR_MAX_SNAPSHOT_AGE_MS
                                            ) {

                                                prAction = "DENY";
                                                prReason = "SNAPSHOT_STALE";
                                            }

                                            else if (
                                                !snap.decision ||
                                                snap.decision.valid !== true
                                            ) {

                                                prAction = "DENY";

                                                prReason =
                                                    snap.decision &&
                                                        typeof snap.decision.reason === "string"
                                                        ? snap.decision.reason
                                                        : "DECISION_NOT_READY";
                                            }

                                            else if (
                                                snap.decision
                                                    .allow_night_dry_start !== true
                                            ) {

                                                prAction = "DENY";

                                                prReason =
                                                    typeof snap.decision.reason === "string"
                                                        ? snap.decision.reason
                                                        : "ENERGY_DENY";
                                            }

                                            else {

                                                prAction = "ALLOW";
                                                prReason = "ALLOW";
                                            }
                                        }
                                    }
                                }
                            }


                            // ==================================================
                            // COMMIT NIGHT_DRY
                            //
                            // È intenzionalmente lo stesso codice legacy.
                            // Viene eseguito:
                            //
                            // - PR OFF  -> BYPASS
                            // - PR ACTIVE + decisione valida -> ALLOW
                            // ==================================================

                            if (
                                prAction === "BYPASS" ||
                                prAction === "ALLOW"
                            ) {

                                statoAttuale = "NIGHT_DRY";

                                flow.set(
                                    "condizionatore_stato",
                                    "NIGHT_DRY",
                                    "file"
                                );

                                global.set(
                                    "ultimo_avvio",
                                    adesso,
                                    "file"
                                );

                                // PR-ACTIVE.2B.5
                                // Commit del comando candidato già preselezionato.
                                comandoIR = candidateCommandIR;

                                if (prAction === "ALLOW") {
                                    motivoAc =
                                        "ESECUZIONE_ACCENSIONE_NOTTURNA_PR";
                                } else {
                                    motivoAc =
                                        "ESECUZIONE_ACCENSIONE_NOTTURNA";
                                }
                            }


                            // ==================================================
                            // DENY
                            //
                            // Nessuna mutazione:
                            // - statoAttuale resta OFF
                            // - condizionatore_stato non viene scritto
                            // - ultimo_avvio non viene scritto
                            // - comandoIR non viene prodotto
                            // ==================================================

                            else {

                                motivoAc =
                                    "BLOCCO_PR_" + prReason;
                            }
                        }
                    }
                }
            } 
            else {
                let richiediSpegnimento = false;
                let richiediStandby = false;

                if (!bloccoSpegnimentoEmergenza) {
                    motivoAc = `MANTENIMENTO_${statoAttuale}`;
                }

                if (statoAttuale === "COOLING_ON" || statoAttuale === "STANDBY_INVERTER") {
                    let limiteDeficitSurplus = soc > 95 ? -1500 : -300;

                    if (esSeraFasciaDinamica) {
                        if (soc > 90) limiteDeficitSurplus = -2000;      
                        else if (soc > 80) limiteDeficitSurplus = -1000; 
                        else if (soc > 70) limiteDeficitSurplus = -400;  
                        else limiteDeficitSurplus = -100;                
                    }

                    if (isPeriodoDiGrazia && usaSoloSolare) {
                        limiteDeficitSurplus = 500; 
                    }

                    let sogliaSpegnimentoComfort = 26;

                    if (isPeriodoDiGrazia && !usaSoloSolare) {
                        if (humidex > EMERGENCY_HUMIDEX_AWAY) {
                            sogliaSpegnimentoComfort = EMERGENCY_HUMIDEX_AWAY; 
                        } else {
                            richiediStandby = true; 
                        }
                    } else {
                        let ampiezzaIsteresi = 2.5; 
                        sogliaSpegnimentoComfort = sogliaAttivazioneLogica - ampiezzaIsteresi;
                    }

                    if (bloccoSpegnimentoEmergenza) {
                        richiediSpegnimento = true; 
                        flow.set("inizio_deficit_surplus", 0);
                    }
                    else if (humidex <= sogliaSpegnimentoComfort) {
                        richiediStandby = true;
                        flow.set("inizio_deficit_surplus", 0);
                        if (minMancantiSpegnimento > 0) motivoAc = "COMFORT_RAGGIUNTO_ATTESA_TIMER";
                        else motivoAc = "STANDBY_COMFORT_RAGGIUNTO";
                    }
                    else if (surplus < limiteDeficitSurplus) {
                        let inizioDeficit = flow.get("inizio_deficit_surplus") || 0;
                        if (inizioDeficit === 0) {
                            flow.set("inizio_deficit_surplus", adesso);
                            motivoAc = "DEFICIT_RILEVATO_AVVIO_TIMER";
                        } else {
                            if ((adesso - inizioDeficit) >= DEFICIT_TOLERANCE_TIME) {
                                if (soc < socMinimoLogico && !solareForteAttivo) {
                                    richiediSpegnimento = true; 
                                } else {
                                    richiediStandby = true; 
                                    motivoAc = "STANDBY_DEFICIT_SOLARE";
                                }
                            } else {
                                motivoAc = "TOLLERANZA_DEFICIT_IN_CORSO";
                            }
                        }
                    }
                    else {
                        if (flow.get("inizio_deficit_surplus")) {
                            flow.set("inizio_deficit_surplus", 0);
                        }

                        if (statoAttuale === "STANDBY_INVERTER" && humidex >= sogliaAttivazioneLogica) {
                            statoAttuale = "COOLING_ON"; 
                            flow.set("condizionatore_stato", "COOLING_ON", "file"); 
                            global.set("ultimo_avvio", adesso, "file");
                            if (temp >= 26) comandoIR = "23"; else if (temp >= 25) comandoIR = "24"; else if (temp >= 24) comandoIR = "23"; else if (temp >= 23) comandoIR = "22"; else comandoIR = "26";
                            motivoAc = "RIPRESA_COOLING_DA_STANDBY";
                        }
                    }

                    if ((soc <= socMinimoLogico && !solareForteAttivo && !bloccoSpegnimentoEmergenza) || esNotteFascia) {
                        richiediSpegnimento = true;
                        richiediStandby = false;
                    }
                }

                if (statoAttuale === "NIGHT_DRY") {
                    if (soc <= socMinimoLogico) {
                        richiediSpegnimento = true;
                        flow.set("ultimo_spegnimento_notte", adesso, "file");
                        if(minMancantiSpegnimento > 0) motivoAc = "BATTERIA_SCARICA_ATTESA_TIMER";
                    } else if (!esNotteFascia) {
                        richiediSpegnimento = true;
                    }
                }

                let eseguiSpegnimento = bloccoSpegnimentoEmergenza ? true : (richiediSpegnimento && minMancantiSpegnimento === 0);

                if (eseguiSpegnimento) {
                    statoAttuale = "OFF";
                    flow.set("condizionatore_stato", "OFF", "file");
                    global.set("ultimo_spegnimento", adesso, "file");
                    comandoIR = "OFF";
                    flow.set("inizio_deficit_surplus", 0); 
                    if (!bloccoSpegnimentoEmergenza) motivoAc = "ESECUZIONE_SPEGNIMENTO";
                } 
                else if (richiediStandby && statoAttuale !== "STANDBY_INVERTER" && minMancantiSpegnimento === 0) {
                    statoAttuale = "STANDBY_INVERTER";
                    flow.set("condizionatore_stato", "STANDBY_INVERTER", "file");
                    global.set("ultimo_spegnimento", adesso, "file");
                    comandoIR = "28"; 
                    flow.set("inizio_deficit_surplus", 0);
                    motivoAc = "ESECUZIONE_STANDBY_INVERTER";
                }
            }
        }
    }

    // ==================================================
    // B.3 LOGICA VMC 
    // ==================================================
    if (MODALITA_STAGIONE === "ESTATE") {
        if (tempEsterna < (temp - 1.5)) {
            velocitaVmc = 3;
            motivoVmc = "FREE_COOLING_ATTIVO";
        }
        else if (tempEsterna >= (temp + 0.5)) {
            velocitaVmc = 1;
            motivoVmc = "SCUDO_TERMICO_ATTIVO";
        }
        else {
            if (humidex >= 30 && humidexEsterno < (humidex + 2.0)) {
                velocitaVmc = 3;
                motivoVmc = "ESTRAZIONE_UMIDITA_ALTA";
            }
            else if (humidex >= 27 && humidexEsterno < (humidex + 2.0)) {
                velocitaVmc = 2;
                motivoVmc = "ESTRAZIONE_UMIDITA_MEDIA";
            }
            else {
                velocitaVmc = 1;
                motivoVmc = "RICAMBIO_ARIA_BASE";
            }
        }
    }
    else {
        let urInterna = esNotteFascia ? flow.get("umidita_bedroom") : flow.get("umidita_living");
        if (urInterna === undefined) urInterna = 50;

        if (urInterna >= 65) { velocitaVmc = 3; motivoVmc = "ANTI_CONDENSA_MASSIMO"; }
        else if (urInterna >= 55) { velocitaVmc = 2; motivoVmc = "ANTI_CONDENSA_MEDIO"; }
        else if (tempEsterna < (temp - 5.0) && urInterna < 50) { velocitaVmc = 1; motivoVmc = "SCUDO_TERMICO_INVERNALE_ATTIVO"; }
        else { velocitaVmc = 1; motivoVmc = "COMFORT_INVERNALE_BASE"; }
    }

    if (esNotteFascia && velocitaVmc > VMC_MAX_NOTTE) { velocitaVmc = VMC_MAX_NOTTE; motivoVmc = motivoVmc + "_LIMITATO_NOTTE"; }
}

let currentTime = Date.now();
let lastVmcChangeTime = flow.get('vmc_ultimo_cambio_ms') || 0;
let lastVmcSpeed = flow.get("vmc_velocita_inviata") || velocitaVmc; 
let cooldownMs = 5 * 60 * 1000; 

if (velocitaVmc !== lastVmcSpeed) {
    if (currentTime - lastVmcChangeTime < cooldownMs) {
        velocitaVmc = lastVmcSpeed;
        motivoVmc = "BLOCCO_ANTIRIMBALZO_ATTIVO";
    } else {
        flow.set('vmc_ultimo_cambio_ms', currentTime);
    }
}

flow.set("vmc_fanspeed", velocitaVmc);

if (!aiAbilitata) {
    flow.set("ac_log_temp", 0, "file");
    flow.set("ac_log_mode", "OFF", "file");
} else if (comandoIR) {
    let estrazioneTesto = comandoIR.match(/\d+/);
    let targetImpostato = estrazioneTesto ? parseFloat(estrazioneTesto[0]) : 0;

    if (comandoIR === "OFF" || comandoIR === "stop") { 
        flow.set("ac_log_temp", 0, "file"); flow.set("ac_log_mode", "OFF", "file"); 
    }
    else if (comandoIR.includes("dry")) { 
        flow.set("ac_log_temp", targetImpostato || 25.0, "file"); flow.set("ac_log_mode", "Deumidificazione", "file"); 
    }
    else if (comandoIR.includes("heat")) { 
        flow.set("ac_log_temp", targetImpostato || 19.0, "file"); flow.set("ac_log_mode", "Riscaldamento", "file"); 
    }
    else { 
        flow.set("ac_log_temp", targetImpostato || 24.0, "file"); flow.set("ac_log_mode", "Raffrescamento", "file"); 
    }
} else if (statoAttuale === "OFF") {
    flow.set("ac_log_temp", 0, "file"); flow.set("ac_log_mode", "OFF", "file");
}

let tempImpostata = flow.get("ac_log_temp", "file") || 0;
let modalitaAria = flow.get("ac_log_mode", "file") || "OFF";

// --- DATI PER L'APP ANDROID (UI E WIDGET) ---
let datiAndroid = {
    timestamp: adesso,
    data_ora_formattata: dataOraFormattata,
    stagione_attiva: MODALITA_STAGIONE,
    metriche_elettriche: {
        produzione_fv_w: prod, 
        consumo_casa_w: cons, 
        surplus_w: surplus,
        grid_power_w: gridPowerRaw,
        grid_import_w: gridImportW,
        grid_export_w: gridExportW,
        battery_power_w: batteryPowerRaw,
        battery_charge_w: batteryChargeW,
        battery_discharge_w: batteryDischargeW,
        powerwall_soc_percent: soc, 
        consumo_ac_w: acPower, 
        consumo_medio_storico_fascia_w: consumoStoricoAttuale
    },
    metriche_ambientali: {
        temp_cameraMatrimoniale: temp_cameraMatrimoniale, temperatura_c: temp,
        humidex: humidex, humidex_living: hGiorno, humidex_bedroom: hNotte,
        altitudine_sole: sunAltitude
    },
    logica_controllo: {
        vmc_portata_stimata_m3h: vmc_portata[velocitaVmc],
        stanza_rilevamento_vmc: esNotteFascia ? "BEDROOM" : "LIVING",
        soglia_attivazione_applicata: sogliaAttivazioneLogica,
        soc_minimo_applied: socMinimoLogico,
        tempo_mancante_anticiclo_minuti: tempoMancanteMinuti,
        previsione_solare_domani_kwh: kwhDomani, previsione_solare_data: dataDomani,
        previsione_ricarica_batteria_percent: percentualeRicaricaPrevista, 
        kwh_stimati_in_batteria: parseFloat(kwhDestinatiAllaBatteria.toFixed(1)),
        blocco_emergenza_attivo: bloccoSpegnimentoEmergenza,
        cuscinetto_sicurezza_kwh: parseFloat(cuscinettoSicurezzaKwh.toFixed(2)),
        cuscinetto_richiesto_kwh: parseFloat(cuscinettoMinimoRichiesto.toFixed(2))
    },
    stato_condizionatore: {
        stato_attuale: statoAttuale,
        motivo_logica: motivoAc,
        temperatura_impostata_c: tempImpostata,
        modalita_aria: modalitaAria
    },
    stato_vmc: {
        velocita_attuale: velocitaVmc, motivo_logica: motivoVmc,
        humidex_esterno: humidexEsterno, temperatura_esterna_c: tempEsterna
    }
};

// --- LOGGING STRUTTURATO PER STORICO E GRAFANA ---
let msgLog = null;
let precedenteStatoAC = flow.get("log_ultimo_stato_ac") || "OFF";
let precedenteVelocitaVMC = flow.get("log_ultima_vmc") || 1;
let precedenteMotivoAC = flow.get("log_ultimo_motivo_ac") || "";

if (comandoIR || statoAttuale !== precedenteStatoAC || velocitaVmc !== precedenteVelocitaVMC || motivoAc !== precedenteMotivoAC) {
    msgLog = {
        payload: {
            timestamp: adesso, data_ora: dataOraFormattata, evento: "CAMBIO_STATO_SISTEMA",
            dettaglio_comandi: {
                comando_ir_inviato: comandoIR || "NESSUNO", stato_ac_precedente: precedenteStatoAC, stato_ac_attuale: statoAttuale,
                vmc_velocita_precedente: precedenteVelocitaVMC, vmc_velocita_attuale: velocitaVmc, motivo_logica: motivoVmc,
                humidex_esterno: humidexEsterno, temperatura_esterna_c: tempEsterna, modalita_aria: modalitaAria, temperatura_impostata_c: tempImpostata
            },
            condizioni_ambientali: { 
                humidex_living: hGiorno, humidex_bedroom: hNotte, temperatura_c: temp, temp_cameraMatrimoniale: temp_cameraMatrimoniale, 
                humidex: humidex, stanza_rilevamento: esNotteFascia ? "BEDROOM" : "LIVING", altitudine_sole: sunAltitude 
            },
            stato_energia: { 
                produzione_w: prod, consumo_w: cons, surplus_w: surplus, powerwall_soc_percent: soc, consumo_ac_w: acPower, soc_minimo_applied: socMinimoLogico,
                grid_import_w: gridImportW, grid_export_w: gridExportW, battery_charge_w: batteryChargeW, battery_discharge_w: batteryDischargeW
            },
            logica_controllo: { 
                previsione_solare_domani_kwh: kwhDomani, previsione_solare_data: dataDomani, previsione_ricarica_batteria_percent: percentualeRicaricaPrevista, 
                kwh_stimati_in_batteria: parseFloat(kwhDestinatiAllaBatteria.toFixed(1)), motivo_ac: motivoAc,
                blocco_emergenza_attivo: bloccoSpegnimentoEmergenza, cuscinetto_sicurezza_kwh: parseFloat(cuscinettoSicurezzaKwh.toFixed(2)),
                cuscinetto_richiesto_kwh: parseFloat(cuscinettoMinimoRichiesto.toFixed(2))
            }
        },
        topic: "casa/clima/log_eventi"
    };
    flow.set("log_ultimo_stato_ac", statoAttuale);
    flow.set("log_ultima_vmc", velocitaVmc);
    flow.set("log_ultimo_motivo_ac", motivoAc);
}

let msgBroadlink = comandoIR ? { payload: comandoIR, topic: "broadlink/cmd" } : null;
let baseTopic = global.get("app_base_topic", "file") || "zara/android/domotica";
let msgAndroid = { payload: datiAndroid, topic: `${baseTopic}/casa/clima/stato_completo` };

let ultimaVelocitaInviata = flow.get("vmc_velocita_inviata") || -1;
let msgVmc = null; 

if (velocitaVmc !== ultimaVelocitaInviata) {
    msgVmc = { topic: "/esp8266/brink/fanspeed", payload: velocitaVmc };
    flow.set("vmc_velocita_inviata", velocitaVmc);
}

return [msgBroadlink, msgAndroid, msgVmc, msgLog, msgHealth];

// ==================================================
// ACTIVE.4C.2G.2
// AI Climate NIGHT_DRY Commit
//
// Unico punto di commit dopo handshake PR causale.
//
// IMPORTANTE:
// - accetta SOLO richieste originate dal vero AI Climate
// - richiede ALLOW esplicito
// - verifica correlazione request/candidate/transition
// - qualsiasi anomalia => NO COMMIT
// ==================================================

const response = msg.payload;
const ctx = msg._pr_prestart;


// --------------------------------------------------
// 1. STRUTTURA MINIMA
// --------------------------------------------------

if (
    !response ||
    typeof response !== "object" ||
    !ctx ||
    typeof ctx !== "object"
) {
    node.warn("PR_PRESTART_COMMIT_DENY: missing response/context");
    return null;
}


// --------------------------------------------------
// 2. SOLO VERO CONSUMER AI CLIMATE
//
// Impedisce all'Inject controllato 2G.1 di effettuare
// un commit anche se PR risponde ALLOW.
// --------------------------------------------------

if (ctx.source !== "AI_CLIMATE_REAL") {
    node.warn(
        "PR_PRESTART_COMMIT_DENY: non-production source=" +
        String(ctx.source)
    );
    return null;
}


// --------------------------------------------------
// 3. VALIDAZIONE CAUSALE FAIL-CLOSED
// --------------------------------------------------

const allowed =
    response.schema ===
        "domopi.predictive_reserve.prestart_result.v1" &&

    typeof response.request_id === "string" &&
    response.request_id.length > 0 &&

    response.request_id ===
        ctx.request_id &&

    response.candidate_command ===
        ctx.candidate_command &&

    response.transition ===
        "OFF_TO_NIGHT_DRY" &&

    response.action ===
        "ALLOW" &&

    response.reason ===
        "ALLOW" &&

    response.authority &&
    response.authority.operating_mode ===
        "ACTIVE" &&

    response.authority.authority_allowed ===
        true &&

    response.authority.effective_authority ===
        true &&

    response.decision &&
    response.decision.valid ===
        true &&

    response.decision.allow_night_dry_start ===
        true;


if (!allowed) {
    node.warn(
        "PR_PRESTART_COMMIT_DENY: validation failed" +
        " request_id=" +
        String(response.request_id) +
        " action=" +
        String(response.action) +
        " reason=" +
        String(response.reason)
    );

    return null;
}


// --------------------------------------------------
// 4. CANDIDATO AMMESSO
// --------------------------------------------------

const candidate =
    ctx.candidate_command;

const supportedCandidates = [
    "eco26dry",
    "eco25dry",
    "25dry",
    "24dry",
    "23dry"
];

if (!supportedCandidates.includes(candidate)) {
    node.warn(
        "PR_PRESTART_COMMIT_DENY: unsupported candidate=" +
        String(candidate)
    );

    return null;
}


// --------------------------------------------------
// 5. COMMIT AI CLIMATE
//
// AI Climate resta owner dello stato climatico.
// PR non scrive queste variabili.
// --------------------------------------------------

const commitTime =
    Date.now();

flow.set(
    "condizionatore_stato",
    "NIGHT_DRY",
    "file"
);

global.set(
    "ultimo_avvio",
    commitTime,
    "file"
);


// --------------------------------------------------
// 6. COSTRUZIONE COMANDO
//
// In 2G.2 il percorso fisico MQTT resta DISABLED.
// --------------------------------------------------

msg.topic =
    "broadlink/cmd";

msg.payload =
    candidate;

msg._ai_climate_commit = {
    schema:
        "domopi.ai_climate.prestart_commit.v1",

    request_id:
        response.request_id,

    committed_at_ms:
        commitTime,

    transition:
        "OFF_TO_NIGHT_DRY",

    candidate_command:
        candidate,

    reason:
        "ESECUZIONE_ACCENSIONE_NOTTURNA_PR"
};

return msg;

// ==================================================
// 0. CONTROLLO DI COERENZA (SANITY CHECK) & FAIL-SAFE
// ==================================================
// --- CONTROLLO DI COERENZA E STATO PERSISTENTE ---
let variabiliCritiche = [
    { nome: "user_min_run_time", defaultVal: 15 },
    { nome: "user_min_off_time", defaultVal: 20 },
    { nome: "user_deficit_tolerance_time", defaultVal: 40 },
    { nome: "user_vmc_max_notte", defaultVal: 2 },
    { nome: "user_target_humidex_estate", defaultVal: 29.0 },
    { nome: "user_emergency_humidex_away", defaultVal: 33.0 },
    { nome: "grace_mode_solar", defaultVal: false }
];

let mancanti = [];

variabiliCritiche.forEach(v => {
    let val = global.get(v.nome, "file");
    if (val === undefined) {
        mancanti.push(v.nome);
        global.set(v.nome, v.defaultVal, "file");
    }
});

let msgHealth = {
    topic: "casa/clima/system_health/stat"
};

if (mancanti.length > 0) {
    node.warn("STATO SISTEMA INCONSISTENTE: Parametri globali mancanti su file -> " + mancanti.join(", "));
    msgHealth.payload = {
        stato: "INCONSISTENTE",
        motivo: "Mancanza di parametri globali persistenti, ripristinati i default",
        elementi_mancanti: mancanti,
        timestamp: Date.now()
    };
} else {
    msgHealth.payload = {
        stato: "NORMALE",
        timestamp: Date.now()
    };
}

// ==================================================
// 1. MEMORIZZAZIONE DEI DATI IN INGRESSO
// ==================================================
if (msg.topic === "system/boot") {
    // Boot sync
}
else if (msg.topic === "TeslaPowerwall/solar_instant_power") {
    flow.set("produzione", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/load_instant_power") {
    flow.set("consumo", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/site_instant_power") {
    flow.set("grid_power", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/battery_instant_power") {
    flow.set("battery_power", parseFloat(msg.payload), "file");
}
else if (msg.topic === "emon/planetary/altitude") {
    flow.set("sun_altitude", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/SOE") {
    let rawSoc = parseFloat(msg.payload);
    let lastValidSoc = flow.get("powerwall_soc", "file");

    if (lastValidSoc === undefined) {
        flow.set("powerwall_soc", rawSoc, "file");
    } else {
        let delta = Math.abs(rawSoc - lastValidSoc);
        if (delta <= 3.0) {
            flow.set("powerwall_soc", rawSoc, "file");
            flow.set("soc_glitch_count", 0, "file"); 
        } else {
            let glitchCount = flow.get("soc_glitch_count", "file") || 0;
            glitchCount++;
            if (glitchCount >= 5) {
                flow.set("powerwall_soc", rawSoc, "file");
                flow.set("soc_glitch_count", 0, "file");
            } else {
                flow.set("soc_glitch_count", glitchCount, "file");
            }
        }
    }
}
else if (msg.topic === "emon/emonth5/temperature_calibrated") {
    flow.set("temperatura", parseFloat(msg.payload),"file");
}
else if (msg.topic === "zara/domotics/LivingHumidex") {
    flow.set("humidex_giorno", parseFloat(msg.payload), "file");
}
else if (msg.topic === "zara/domotics/BedroomHumidex") {
    flow.set("humidex_notte", parseFloat(msg.payload), "file");
}
else if (msg.topic === "zigbee2mqtt/Sonoff AirGuard TH esterno cucina") {
    flow.set("temp_esterno", parseFloat(msg.payload.temperature));
    flow.set("umidita_esterno", parseFloat(msg.payload.humidity));
}
else if (msg.topic === "emon/cameraMatrimoniale/temperature") {
    flow.set("temp_cameraMatrimoniale", parseFloat(msg.payload));
}
else if (msg.topic === "emon/AC/emeter_power") {
    flow.set("ac_power", Math.abs(parseFloat(msg.payload)), "file"); 
}

let meseAttuale = new Date().getMonth();
let MODALITA_STAGIONE = (meseAttuale >= 4 && meseAttuale <= 8) ? "ESTATE" : "INVERNO";

let tempEsterna = flow.get("temp_esterno");
let umiditaEsterna = flow.get("umidita_esterno");

if (tempEsterna === undefined || umiditaEsterna === undefined) {
    tempEsterna = (MODALITA_STAGIONE === "ESTATE") ? 24 : 8;
    umiditaEsterna = 60;
}

let aEst = 17.27;
let bEst = 237.7;
let alphaEst = ((aEst * tempEsterna) / (bEst + tempEsterna)) + Math.log(umiditaEsterna / 100);
let dewPointEst = (bEst * alphaEst) / (aEst - alphaEst);
let eEst = 6.11 * Math.exp(5417.7530 * ((1 / 273.15) - (1 / (273.15 + dewPointEst))));
let humidexEsterno = parseFloat((tempEsterna + (5 / 9) * (eEst - 10)).toFixed(1));

let adesso = Date.now();
let statoAttuale = flow.get("condizionatore_stato", "file") || "OFF";

let ultimoAvvio = global.get("ultimo_avvio", "file") || (adesso - 40 * 60 * 1000);
let ultimoSpegnimento = global.get("ultimo_spegnimento", "file") || (adesso - 40 * 60 * 1000);

const MIN_RUN_MINUTI = parseFloat(global.get("user_min_run_time", "file")) || 15;
const MIN_OFF_MINUTI = parseFloat(global.get("user_min_off_time", "file")) || 15;
const DEFICIT_TOLERANCE_MINUTI = parseFloat(global.get("user_deficit_tolerance_time", "file")) || 10; 
const VMC_MAX_NOTTE = parseInt(global.get("user_vmc_max_notte", "file")) || 2;
const TARGET_HUMIDEX_ESTATE = parseFloat(global.get("user_target_humidex_estate", "file")) || 29;
const EMERGENCY_HUMIDEX_AWAY = parseFloat(global.get("user_emergency_humidex_away", "file")) || 33.0;

const MIN_RUN_TIME = MIN_RUN_MINUTI * 60 * 1000;
const MIN_OFF_TIME = MIN_OFF_MINUTI * 60 * 1000;
const DEFICIT_TOLERANCE_TIME = DEFICIT_TOLERANCE_MINUTI * 60 * 1000; 

let tempoPassatoDallAccensione = adesso - ultimoAvvio;
let tempoPassatoDalloSpegnimento = adesso - ultimoSpegnimento;

let minMancantiSpegnimento = tempoPassatoDallAccensione < MIN_RUN_TIME ? Math.ceil((MIN_RUN_TIME - tempoPassatoDallAccensione) / 60000) : 0;
let minMancantiAccensione = tempoPassatoDalloSpegnimento < MIN_OFF_TIME ? Math.ceil((MIN_OFF_TIME - tempoPassatoDalloSpegnimento) / 60000) : 0;
let tempoMancanteMinuti = (statoAttuale === "OFF") ? minMancantiAccensione : minMancantiSpegnimento;

// ==================================================
// 2. RECUPERO DERIVAZIONI ENERGETICHE E ASTRONOMICHE
// ==================================================
let prod = flow.get("produzione", "file") || 0;
let cons = flow.get("consumo", "file") || 0;
let soc = (flow.get("powerwall_soc", "file") !== undefined) ? flow.get("powerwall_soc", "file") : 0;
let temp = flow.get("temperatura", "file") || 19;
let hGiorno = flow.get("humidex_giorno", "file") || 0;
let hNotte = flow.get("humidex_notte", "file") || 0;
let temp_cameraMatrimoniale = flow.get("temp_cameraMatrimoniale") || 0;
let acPower = flow.get("ac_power", "file") || 0;

let gridPowerRaw = flow.get("grid_power", "file") || 0;
let batteryPowerRaw = flow.get("battery_power", "file") || 0;
let sunAltitude = flow.get("sun_altitude", "file"); 
if (sunAltitude === undefined) sunAltitude = 90; 

let gridImportW = Math.max(gridPowerRaw, 0);
let gridExportW = Math.max(-gridPowerRaw, 0);
let batteryDischargeW = Math.max(batteryPowerRaw, 0);
let batteryChargeW = Math.max(-batteryPowerRaw, 0);

let vmc_portata = [0, 50, 130, 160, 300];
let oraAttuale = new Date().getHours();
let surplus = prod - cons;

let kwhDomani = flow.get("previsione_kwh_domani") || 12;
let dataDomani = flow.get("previsione_data_domani") || "N/A";
let tutteMedie = flow.get("tutte_medie_storiche", "file") || global.get("tutte_medie_storiche", "file") || { ESTATE: { GIORNO: 600, NOTTE: 400 }, INVERNO: { GIORNO: 800, NOTTE: 500 } };

let dataOraFormattata = new Intl.DateTimeFormat('it-IT', {
    timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false
}).format(new Date(adesso));

let esNotteFascia = (oraAttuale >= 22 || oraAttuale < 8);
let humidex = esNotteFascia ? hNotte : hGiorno;
if (humidex === 0) humidex = (hGiorno !== 0) ? hGiorno : hNotte;

const CAPACITA_BATTERIA_KWH = 13.5;
let consumoDiurnoStimatoKwh = (tutteMedie[MODALITA_STAGIONE]["GIORNO"] * 12) / 1000;
if (isNaN(consumoDiurnoStimatoKwh) || consumoDiurnoStimatoKwh < 3) consumoDiurnoStimatoKwh = 7.5;

let energiaDisponibilePerBatteriaKwh = (kwhDomani - consumoDiurnoStimatoKwh) * 0.95;
if (energiaDisponibilePerBatteriaKwh < 0) energiaDisponibilePerBatteriaKwh = 0;

let socStimatoMattino = soc - 15;
if (socStimatoMattino < 0) socStimatoMattino = 0;
if (socStimatoMattino > 100) socStimatoMattino = 100; 

let capacitaVuotaKwh = CAPACITA_BATTERIA_KWH * (1 - (socStimatoMattino / 100));
let kwhDestinatiAllaBatteria = 0;
let percentualeRicaricaPrevista = 0;

if (energiaDisponibilePerBatteriaKwh >= capacitaVuotaKwh) {
    kwhDestinatiAllaBatteria = capacitaVuotaKwh;
    percentualeRicaricaPrevista = 100;
} else {
    kwhDestinatiAllaBatteria = energiaDisponibilePerBatteriaKwh;
    let ricaricaAggiuntivaPercentuale = (energiaDisponibilePerBatteriaKwh / CAPACITA_BATTERIA_KWH) * 100;
    percentualeRicaricaPrevista = Math.round(socStimatoMattino + ricaricaAggiuntivaPercentuale);
}

if (percentualeRicaricaPrevista > 100) percentualeRicaricaPrevista = 100;
if (percentualeRicaricaPrevista < 0) percentualeRicaricaPrevista = 0;

let comandoIR = null;
// ACTIVE.4C.2G.1
// Richiesta pre-start PR causale.
// Rimane null salvo candidatura reale OFF -> NIGHT_DRY con PR ON.
let msgPrPrestart = null;
let sogliaAttivazioneLogica = 0;
let socMinimoLogico = 0;
let consumoStoricoAttuale = tutteMedie[MODALITA_STAGIONE][esNotteFascia ? "NOTTE" : "GIORNO"];

// --- Inizializzazione Variabili per Log e UI ---
let bloccoSpegnimentoEmergenza = false; 
let energiaDisponibileKwh = 0;
let consumoNotteStimatoKwh = 0;
let cuscinettoSicurezzaKwh = 0;
let cuscinettoMinimoRichiesto = 0;

// ==================================================
// 3. MASTER SWITCH E LOGICA INTEGRATA
// ==================================================
let aiAbilitata = flow.get("AI_climate_enabling", "file");
if (aiAbilitata === undefined) {
    aiAbilitata = true;
    flow.set("AI_climate_enabling", true, "file");
}
let systemWasDisabled = flow.get("system_was_disabled") || false;

let velocitaVmc = 1;
let motivoVmc = "STANDBY_MINIMO";
let motivoAc = "ANALISI_IN_CORSO";

if (!aiAbilitata) {
    if (!systemWasDisabled) {
        comandoIR = "OFF"; 
        statoAttuale = "OFF";
        flow.set("condizionatore_stato", "OFF", "file");
        flow.set("system_was_disabled", true);
        global.set("ultimo_spegnimento", adesso, "file");
    } else {
        statoAttuale = "OFF";
    }
    velocitaVmc = 1;
    motivoVmc = "SISTEMA_DISABILITATO";
    motivoAc = "SISTEMA_DISABILITATO_DA_UTENTE";
    tempoMancanteMinuti = 0;

} else {
    if (systemWasDisabled) {
        flow.set("system_was_disabled", false);
    }

    let bypassRoutine = false;

    if (statoAttuale !== "OFF" && acPower >= 10) {
        flow.set("tentativi_riavvio_ac", 0);
    }

    if (statoAttuale === "OFF" && acPower > 30 && (adesso - ultimoSpegnimento > 3 * 60 * 1000)) {
        comandoIR = "OFF";
        global.set("ultimo_spegnimento", adesso, "file"); 
        ultimoSpegnimento = adesso;                      
        motivoAc = "WATCHDOG_FALSO_OFF";
        bypassRoutine = true; 
    }
    else if (statoAttuale !== "OFF" && statoAttuale !== "STANDBY_INVERTER" && acPower < 10 && (adesso - ultimoAvvio > 6 * 60 * 1000)) {
        let tentativi = flow.get("tentativi_riavvio_ac") || 0;

        if (tentativi < 3) {
            tentativi++;
            flow.set("tentativi_riavvio_ac", tentativi);

            statoAttuale = "OFF";
            flow.set("condizionatore_stato", "OFF", "file");
            global.set("ultimo_spegnimento", adesso - MIN_OFF_TIME - 1000, "file");
            tempoMancanteMinuti = 0;
            minMancantiAccensione = 0;
            motivoAc = "WATCHDOG_TENTATIVO_RIAVVIO_" + tentativi;
        } else {
            aiAbilitata = false;
            flow.set("AI_climate_enabling", false, "file");
            flow.set("tentativi_riavvio_ac", 0);

            comandoIR = "OFF"; 
            statoAttuale = "OFF";
            flow.set("condizionatore_stato", "OFF", "file");
            global.set("ultimo_spegnimento", adesso, "file");
            motivoAc = "WATCHDOG_SOSPENSIONE_SISTEMA_GUASTO";
            bypassRoutine = true;
        }
    }

    if (!bypassRoutine && aiAbilitata) {
        if (MODALITA_STAGIONE === "INVERNO") {
            sogliaAttivazioneLogica = esNotteFascia ? 17.0 : 19.0;
            socMinimoLogico = esNotteFascia ? (kwhDomani >= 22 && consumoStoricoAttuale < 700 ? 25 : (kwhDomani <= 8 || consumoStoricoAttuale > 1000 ? 60 : 40)) : 0;
            motivoAc = "LOGICA_INVERNALE_ATTIVA";

            if (statoAttuale === "OFF") {
                if (!esNotteFascia && surplus > (consumoStoricoAttuale * 0.8) && temp < 19.0) {
                    if (minMancantiAccensione === 0) {
                        statoAttuale = "HEAT_DIURNO"; flow.set("condizionatore_stato", "HEAT_DIURNO", "file"); global.set("ultimo_avvio", adesso, "file"); comandoIR = "eco19heat";
                    }
                }
                else if (esNotteFascia && temp < 17.0 && soc > socMinimoLogico) {
                    if (minMancantiAccensione === 0) {
                        statoAttuale = "HEAT_SICUREZZA_NOTTE"; flow.set("condizionatore_stato", "HEAT_SICUREZZA_NOTTE", "file"); global.set("ultimo_avvio", adesso, "file"); comandoIR = "eco17heat";
                    }
                }
