        else { velocitaVmc = 1; motivoVmc = "COMFORT_INVERNALE_BASE"; }
    }

    if (esNotteFascia && velocitaVmc > VMC_MAX_NOTTE) { velocitaVmc = VMC_MAX_NOTTE; motivoVmc = motivoVmc + "_LIMITATO_NOTTE"; }
}

let currentTime = Date.now();
let lastVmcChangeTime = flow.get('vmc_ultimo_cambio_ms') || 0;
let lastVmcSpeed = flow.get("vmc_velocita_inviata") || velocitaVmc; 
let cooldownMs = 5 * 60 * 1000; 

if (velocitaVmc !== lastVmcSpeed) {
    if (currentTime - lastVmcChangeTime < cooldownMs) {
        velocitaVmc = lastVmcSpeed;
        motivoVmc = "BLOCCO_ANTIRIMBALZO_ATTIVO";
    } else {
        flow.set('vmc_ultimo_cambio_ms', currentTime);
    }
}

flow.set("vmc_fanspeed", velocitaVmc);

if (!aiAbilitata) {
    flow.set("ac_log_temp", 0, "file");
    flow.set("ac_log_mode", "OFF", "file");
} else if (comandoIR) {
    let estrazioneTesto = comandoIR.match(/\d+/);
    let targetImpostato = estrazioneTesto ? parseFloat(estrazioneTesto[0]) : 0;

    if (comandoIR === "OFF" || comandoIR === "stop") { 
        flow.set("ac_log_temp", 0, "file"); flow.set("ac_log_mode", "OFF", "file"); 
    }
    else if (comandoIR.includes("dry")) { 
        flow.set("ac_log_temp", targetImpostato || 25.0, "file"); flow.set("ac_log_mode", "Deumidificazione", "file"); 
    }
    else if (comandoIR.includes("heat")) { 
        flow.set("ac_log_temp", targetImpostato || 19.0, "file"); flow.set("ac_log_mode", "Riscaldamento", "file"); 
    }
    else { 
        flow.set("ac_log_temp", targetImpostato || 24.0, "file"); flow.set("ac_log_mode", "Raffrescamento", "file"); 
    }
} else if (statoAttuale === "OFF") {
    flow.set("ac_log_temp", 0, "file"); flow.set("ac_log_mode", "OFF", "file");
}

let tempImpostata = flow.get("ac_log_temp", "file") || 0;
let modalitaAria = flow.get("ac_log_mode", "file") || "OFF";

// ==================================================
// DIAGNOSTICA TIMER AC - SOLO OSSERVAZIONE
// I valori seguenti non partecipano alla logica di controllo.
// ==================================================
let inizioDeficitDiagnostica =
    flow.get("inizio_deficit_surplus") || 0;

let deficitResiduoMinuti =
    inizioDeficitDiagnostica > 0
        ? Math.max(
            0,
            Math.ceil(
                (
                    DEFICIT_TOLERANCE_TIME -
                    (adesso - inizioDeficitDiagnostica)
                ) / 60000
            )
        )
        : 0;

let ultimoSpegnimentoNotteDiagnostica =
    flow.get("ultimo_spegnimento_notte", "file") || 0;

const PAUSA_NOTTURNA_MINUTI = 45;
const PAUSA_NOTTURNA_TIME =
    PAUSA_NOTTURNA_MINUTI * 60 * 1000;

let pausaNotturnaResiduoMinuti =
    ultimoSpegnimentoNotteDiagnostica > 0 &&
    (adesso - ultimoSpegnimentoNotteDiagnostica) < PAUSA_NOTTURNA_TIME
        ? Math.max(
            0,
            Math.ceil(
                (
                    PAUSA_NOTTURNA_TIME -
                    (adesso - ultimoSpegnimentoNotteDiagnostica)
                ) / 60000
            )
        )
        : 0;

// --- DATI PER L'APP ANDROID (UI E WIDGET) ---
let datiAndroid = {
    timestamp: adesso,
    data_ora_formattata: dataOraFormattata,
    stagione_attiva: MODALITA_STAGIONE,
    metriche_elettriche: {
        produzione_fv_w: prod, 
        consumo_casa_w: cons, 
        surplus_w: surplus,
        grid_power_w: gridPowerRaw,
        grid_import_w: gridImportW,
        grid_export_w: gridExportW,
        battery_power_w: batteryPowerRaw,
        battery_charge_w: batteryChargeW,
        battery_discharge_w: batteryDischargeW,
        powerwall_soc_percent: soc, 
        consumo_ac_w: acPower, 
        consumo_medio_storico_fascia_w: consumoStoricoAttuale
    },
    metriche_ambientali: {
        temp_cameraMatrimoniale: temp_cameraMatrimoniale, temperatura_c: temp,
        humidex: humidex, humidex_living: hGiorno, humidex_bedroom: hNotte,
        altitudine_sole: sunAltitude
    },
    logica_controllo: {
        vmc_portata_stimata_m3h: vmc_portata[velocitaVmc],
        stanza_rilevamento_vmc: esNotteFascia ? "BEDROOM" : "LIVING",

        // ==================================================
        // SOGLIE COMFORT
        // ==================================================
        soglia_attivazione_applicata: sogliaAttivazioneLogica,
        soglia_spegnimento_comfort: sogliaSpegnimentoComfort,
        ampiezza_isteresi_humidex: ampiezzaIsteresi,

        // Soglie temperatura utilizzate dalla logica AC estiva
        soglia_temperatura_avvio_cooling_c: 24.0,
        soglia_temperatura_off_comfort_c: 24.5,

        // ==================================================
        // ENERGIA / BATTERIA
        // ==================================================
        soc_minimo_applied: socMinimoLogico,

        previsione_solare_domani_kwh: kwhDomani,
        previsione_solare_data: dataDomani,
        previsione_ricarica_batteria_percent: percentualeRicaricaPrevista,
        kwh_stimati_in_batteria:
            parseFloat(kwhDestinatiAllaBatteria.toFixed(1)),

        blocco_emergenza_attivo: bloccoSpegnimentoEmergenza,

        cuscinetto_sicurezza_kwh:
            parseFloat(cuscinettoSicurezzaKwh.toFixed(2)),

        cuscinetto_richiesto_kwh:
            parseFloat(cuscinettoMinimoRichiesto.toFixed(2)),

        // ==================================================
        // TIMER LEGACY
        // Mantenuto per compatibilità con i consumer esistenti
        // ==================================================
        tempo_mancante_anticiclo_minuti: tempoMancanteMinuti,

        // ==================================================
        // DIAGNOSTICA AC
        // Informazioni esplicative per la UI Android.
        // Non modificano in alcun modo la logica di controllo.
        // ==================================================
        diagnostica_ac: {

            timer_tipo:
                statoAttuale === "OFF"
                    ? "MIN_OFF"
                    : "MIN_RUN",

            timer_residuo_minuti:
                statoAttuale === "OFF"
                    ? minMancantiAccensione
                    : minMancantiSpegnimento,

            timer_durata_minuti:
                statoAttuale === "OFF"
                    ? MIN_OFF_MINUTI
                    : MIN_RUN_MINUTI,

            deficit_tolleranza_minuti:
                DEFICIT_TOLERANCE_MINUTI,

            deficit_residuo_minuti:
                deficitResiduoMinuti,

            pausa_notturna_residuo_minuti:
                pausaNotturnaResiduoMinuti,

            causa_transizione:
                causaTransizioneAc
        }
    },
    stato_condizionatore: {
        stato_attuale: statoAttuale,
        motivo_logica: motivoAc,
        temperatura_impostata_c: tempImpostata,
        modalita_aria: modalitaAria
    },
    stato_vmc: {
        velocita_attuale: velocitaVmc, motivo_logica: motivoVmc,
        humidex_esterno: humidexEsterno, temperatura_esterna_c: tempEsterna
    }
};

// --- LOGGING STRUTTURATO PER STORICO E GRAFANA ---
let msgLog = null;
let precedenteStatoAC = flow.get("log_ultimo_stato_ac") || "OFF";
let precedenteVelocitaVMC = flow.get("log_ultima_vmc") || 1;
let precedenteMotivoAC = flow.get("log_ultimo_motivo_ac") || "";

if (comandoIR || statoAttuale !== precedenteStatoAC || velocitaVmc !== precedenteVelocitaVMC || motivoAc !== precedenteMotivoAC) {
    msgLog = {
        payload: {
            timestamp: adesso, data_ora: dataOraFormattata, evento: "CAMBIO_STATO_SISTEMA",
            dettaglio_comandi: {
                comando_ir_inviato: comandoIR || "NESSUNO", stato_ac_precedente: precedenteStatoAC, stato_ac_attuale: statoAttuale,
                vmc_velocita_precedente: precedenteVelocitaVMC, vmc_velocita_attuale: velocitaVmc, motivo_logica: motivoVmc,
                humidex_esterno: humidexEsterno, temperatura_esterna_c: tempEsterna, modalita_aria: modalitaAria, temperatura_impostata_c: tempImpostata
            },
            condizioni_ambientali: { 
                humidex_living: hGiorno, humidex_bedroom: hNotte, temperatura_c: temp, temp_cameraMatrimoniale: temp_cameraMatrimoniale, 
                humidex: humidex, stanza_rilevamento: esNotteFascia ? "BEDROOM" : "LIVING", altitudine_sole: sunAltitude 
            },
            stato_energia: { 
                produzione_w: prod, consumo_w: cons, surplus_w: surplus, powerwall_soc_percent: soc, consumo_ac_w: acPower, soc_minimo_applied: socMinimoLogico,
                grid_import_w: gridImportW, grid_export_w: gridExportW, battery_charge_w: batteryChargeW, battery_discharge_w: batteryDischargeW
            },
            logica_controllo: { 
                previsione_solare_domani_kwh: kwhDomani, previsione_solare_data: dataDomani, previsione_ricarica_batteria_percent: percentualeRicaricaPrevista, 
                kwh_stimati_in_batteria: parseFloat(kwhDestinatiAllaBatteria.toFixed(1)), motivo_ac: motivoAc,
                blocco_emergenza_attivo: bloccoSpegnimentoEmergenza, cuscinetto_sicurezza_kwh: parseFloat(cuscinettoSicurezzaKwh.toFixed(2)),
                cuscinetto_richiesto_kwh: parseFloat(cuscinettoMinimoRichiesto.toFixed(2))
            }
        },
        topic: "casa/clima/log_eventi"
    };
    flow.set("log_ultimo_stato_ac", statoAttuale);
    flow.set("log_ultima_vmc", velocitaVmc);
    flow.set("log_ultimo_motivo_ac", motivoAc);
}

let msgBroadlink = comandoIR ? { payload: comandoIR, topic: "broadlink/cmd" } : null;
let baseTopic = global.get("app_base_topic", "file") || "zara/android/domotica";
let msgAndroid = { payload: datiAndroid, topic: `${baseTopic}/casa/clima/stato_completo` };

let ultimaVelocitaInviata = flow.get("vmc_velocita_inviata") || -1;
let msgVmc = null; 

if (velocitaVmc !== ultimaVelocitaInviata) {
    msgVmc = { topic: "/esp8266/brink/fanspeed", payload: velocitaVmc };
    flow.set("vmc_velocita_inviata", velocitaVmc);
}

return [
    msgBroadlink,
    msgAndroid,
    msgVmc,
    msgLog,
    msgHealth,
    msgPrPrestart
];
